let docSession = null;
/** A private session for printing documents and showing pages: nothing from the internet, no permissions. */
function offlineSession(name) {
  const s = session.fromPartition(name);
  s.webRequest.onBeforeRequest((d, cb) => cb({ cancel: !/^(file|data|blob|devtools|chrome-extension):/i.test(d.url) || (/^file:/i.test(d.url) && !okFileUrl(d.url)) }));
  s.setPermissionRequestHandler((_wc, _p, cb) => cb(false));
  s.setPermissionCheckHandler(() => false);
  return s;
}
/** Pages and documents may load Atlas's own fonts and the file itself, nothing else on the PC. */
function okFileUrl(url) {
  try {
    const p = path.resolve(decodeURIComponent(new URL(url).pathname).replace(/^\/([A-Za-z]:)/, '$1'));
    return p.startsWith(path.resolve(FONT_DIR) + path.sep) || p.startsWith(path.resolve(base()) + path.sep) || p.startsWith(path.resolve(os.tmpdir()) + path.sep);
  } catch { return false; }
}

async function printPdf(html) {
  if (!docSession) docSession = offlineSession('atlas-docs');
  const tmp = path.join(os.tmpdir(), `atlas-doc-${process.pid}-${Date.now()}.html`);
  fs.writeFileSync(tmp, html, 'utf8');
  // the page itself can't run script (its CSP blocks it); Atlas only uses script to wait for the fonts
  const win = new BrowserWindow({ show: false, width: 900, height: 1200, webPreferences: { session: docSession, javascript: true, sandbox: true, contextIsolation: true, nodeIntegration: false } });
  win.webContents.setWindowOpenHandler(() => ({ action: 'deny' }));
  win.webContents.on('will-navigate', (e) => e.preventDefault());
  try {
    await win.loadFile(tmp);
    await Promise.race([win.webContents.executeJavaScript('document.fonts ? document.fonts.ready.then(() => 1) : 1', true).catch(() => {}), new Promise((r) => setTimeout(r, 3000))]);
    return await win.webContents.printToPDF({ pageSize: 'A4', printBackground: true, preferCSSPageSize: true });
  } finally { win.destroy(); fs.rm(tmp, { force: true }, () => {}); }
}

// ---------------------------------------------------------------- interactive pages

const TEMPLATE = path.join(__dirname, 'renderer', 'templates', 'page.html');
/** A page from a plain description (title, text, tables, charts): Atlas's own template draws it, with sorting, a filter and charts. */
function pageFromSpec(spec) {
  const tpl = fs.readFileSync(TEMPLATE, 'utf8');
  const data = JSON.stringify(cleanSpec(spec)).replace(/</g, '\\u003c').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');
  return tpl.replace('/*ATLAS_PAGE_DATA*/null', () => data).replace('<title>Atlas Page</title>', () => `<title>${esc(spec.title || 'Atlas Page')}</title>`);
}
/** Only the parts the template knows, with sane sizes. */
function cleanSpec(s) {
  const str = (v, n) => String(v ?? '').slice(0, n);
  const out = { title: str(s.title, 200), intro: str(s.intro || s.text, 20000), sections: [] };
  for (const t of (Array.isArray(s.tables) ? s.tables : []).slice(0, 12)) {
    const columns = (Array.isArray(t.columns) ? t.columns : []).slice(0, 40).map((c) => str(c, 120));
    const rows = (Array.isArray(t.rows) ? t.rows : []).slice(0, 5000).map((r) => (Array.isArray(r) ? r : []).slice(0, 40).map((c) => (typeof c === 'number' ? c : str(c, 1000))));
    out.sections.push({ type: 'table', title: str(t.title, 200), columns, rows });
  }
  for (const c of (Array.isArray(s.charts) ? s.charts : []).slice(0, 12)) {
    const labels = (Array.isArray(c.labels) ? c.labels : []).slice(0, 200).map((x) => str(x, 80));
    const series = (Array.isArray(c.series) ? c.series : []).slice(0, 8).map((x) => ({ name: str(x && x.name, 80), values: (Array.isArray(x && x.values) ? x.values : []).slice(0, 200).map((v) => (Number.isFinite(+v) ? +v : 0)) }));
    out.sections.push({ type: 'chart', title: str(c.title, 200), kind: ['bar', 'line', 'pie'].includes(c.type || c.kind) ? (c.type || c.kind) : 'bar', labels, series });
  }
  return out;
}

let pageSession = null;
/** Opens a page in Atlas's own viewer: its script runs, but it has no internet, no Node, no permissions. */
function openPage(file) {
  if (!pageSession) pageSession = offlineSession('atlas-pages');
  const win = new BrowserWindow({ width: 1100, height: 820, title: path.basename(file), autoHideMenuBar: true, backgroundColor: '#ffffff',
    webPreferences: { session: pageSession, sandbox: true, contextIsolation: true, nodeIntegration: false, javascript: true } });
  win.webContents.setWindowOpenHandler(({ url }) => { if (/^https?:/i.test(url)) shell.openExternal(url); return { action: 'deny' }; });
  win.webContents.on('will-navigate', (e, url) => { e.preventDefault(); if (/^https?:/i.test(url)) shell.openExternal(url); });
  win.loadFile(file);
  return win;
}

// ---------------------------------------------------------------- the tools

/**
 * Runs one of Atlas Bot's file tools for a job. Returns { out, step?, made? } (made: the new file's name, for the report).
 * makeHtml: the document's body as HTML (the renderer turns the bot's Markdown into HTML with Atlas's own renderer).
 */
async function run(jobId, goal, name, args = {}) {
  const dir = folderFor(jobId, goal);
  const when = new Date().toLocaleString(undefined, { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' });
  switch (name) {
    case 'workspace_list': {
      const files = listFiles(dir);
      if (!files.length) return { out: "This job's folder is empty. Files you make, write or download go here." };
      return { out: "Files in this job's folder:\n" + files.map((f) => `- ${f.name} (${fmtSize(f.size)})`).join('\n'), step: 'Looked at its files' };
    }
    case 'workspace_read': {
      const n = fileName(args.name);
      const f = path.join(dir, n);
      if (!fs.existsSync(f)) return { out: `There's no file called "${n}" in this job's folder. Use workspace_list to see what's there.` };
      const ext = path.extname(n).toLowerCase();
      if (!TEXT_EXT.has(ext)) return { out: `"${n}" isn't a text file, so it can't be read here (you can still upload it on a website or mention it in the report).` };
      const text = fs.readFileSync(f, 'utf8');
      const from = Math.max(0, Number(args.from) || 0);
      const part = text.slice(from, from + MAX_READ);
      const more = text.length > from + MAX_READ ? `\n\n[${text.length - from - MAX_READ} more characters: read again with from=${from + MAX_READ}]` : '';
      return { out: part + more, step: 'Read ' + n };
    }
    case 'workspace_write': {
      const n = fileName(args.name);
      const ext = path.extname(n).toLowerCase();
      if (!TEXT_EXT.has(ext)) return { out: 'Only text files can be written this way (.txt, .md, .csv, .json, .html…). For a PDF use make_document; for Excel use make_spreadsheet.' };
      const text = String(args.text ?? '');
      if (Buffer.byteLength(text) > MAX_WRITE) return { out: 'That is too long for one file (1 MB at most). Split it.' };
      fs.mkdirSync(dir, { recursive: true });
      const f = path.join(dir, n);
      const existed = fs.existsSync(f);
      fs.writeFileSync(f, args.append && existed ? fs.readFileSync(f, 'utf8') + text : text, 'utf8');
      remember({ file: f, title: n, kind: 'file', job: jobId, goal: String(goal || ''), at: Date.now() });
      // a working file, not a deliverable: it shows in the Library, but the report's file list is for what make_* produced
      return { out: `${existed ? (args.append ? 'Added to' : 'Replaced') : 'Wrote'} ${n} in this job's folder.`, step: 'Wrote ' + n };
    }
    case 'make_document': {
      const title = String(args.title || 'Document').slice(0, 160);
      const md = String(args.markdown || args.text || '');
      if (!md.trim()) return { out: 'The document is empty: give it the text in Markdown.' };
      fs.mkdirSync(dir, { recursive: true });
      const pdf = await printPdf(documentHtml(title, String(args.html || ''), when));
      const pf = freshPath(dir, fileName(title, '.pdf').replace(/\.[^.]+$/, '') + '.pdf');
      fs.writeFileSync(pf, pdf);
      const mf = pf.replace(/\.pdf$/, '.md');
      fs.writeFileSync(mf, `# ${title}\n\n${md}\n`, 'utf8');
      remember({ file: pf, title, kind: 'document', job: jobId, goal: String(goal || ''), at: Date.now() });
      return { out: `Made the document "${path.basename(pf)}" (PDF, ${fmtSize(pdf.length)}), with the text also saved as ${path.basename(mf)}.`, step: 'Made a document: ' + title.slice(0, 60), made: path.basename(pf) };
    }
    case 'make_spreadsheet': {
      const title = String(args.title || 'Spreadsheet').slice(0, 160);
      const list = Array.isArray(args.sheets) && args.sheets.length ? args.sheets : [{ name: args.sheet || title, columns: args.columns, rows: args.rows }];
      const book = [];
      for (const s of list.slice(0, 20)) {
        const columns = (Array.isArray(s.columns) ? s.columns : []).map((c) => String(c ?? ''));
        let rows = Array.isArray(s.rows) ? s.rows : (typeof s.csv === 'string' ? sheets.parseCsv(s.csv) : []);
        if (!columns.length && typeof s.csv === 'string') rows = rows.slice(0); // the CSV's first row is the header
        rows = rows.slice(0, MAX_ROWS).map((r) => (Array.isArray(r) ? r : Object.values(r || {})).map((v) => (v == null ? '' : typeof v === 'number' ? String(v) : String(v))));
        book.push({ name: s.name || title, rows: columns.length ? [columns, ...rows] : rows });
      }
      if (!book.some((s) => s.rows.length)) return { out: 'The spreadsheet is empty: give it columns and rows.' };
      fs.mkdirSync(dir, { recursive: true });
      const xf = freshPath(dir, fileName(title, '.xlsx').replace(/\.[^.]+$/, '') + '.xlsx');
      fs.writeFileSync(xf, sheets.xlsx(book));
      const cf = xf.replace(/\.xlsx$/, '.csv');
      fs.writeFileSync(cf, '﻿' + sheets.toCsv(book[0].rows), 'utf8');
      remember({ file: xf, title, kind: 'spreadsheet', job: jobId, goal: String(goal || ''), at: Date.now() });
      const rowsN = book.reduce((n, s) => n + Math.max(0, s.rows.length - 1), 0);
      return { out: `Made the spreadsheet "${path.basename(xf)}" (Excel, ${book.length} sheet${book.length === 1 ? '' : 's'}, ${rowsN} rows), plus ${path.basename(cf)} for the first sheet.`, step: 'Made a spreadsheet: ' + title.slice(0, 60), made: path.basename(xf) };
    }
    case 'make_page': {
      const title = String(args.title || 'Page').slice(0, 160);
      let html;
      if (typeof args.html === 'string' && args.html.trim()) {
        if (Buffer.byteLength(args.html) > MAX_PAGE) return { out: 'That page is too big (2 MB at most).' };
        html = args.html;
      } else {
        const spec = { title, intro: args.intro || args.text || '', tables: args.tables, charts: args.charts };
        if (!spec.intro && !(spec.tables || []).length && !(spec.charts || []).length) return { out: 'The page is empty: give it some text, tables or charts.' };
        html = pageFromSpec(spec);
      }
      fs.mkdirSync(dir, { recursive: true });
      const f = freshPath(dir, fileName(title, '.html').replace(/\.[^.]+$/, '') + '.html');
      fs.writeFileSync(f, html, 'utf8');
      remember({ file: f, title, kind: 'page', job: jobId, goal: String(goal || ''), at: Date.now() });
      return { out: `Made the page "${path.basename(f)}". It opens in Atlas's viewer from the Library.`, step: 'Made a page: ' + title.slice(0, 60), made: path.basename(f) };
    }
    default: return { out: 'Error: there is no such file tool.' };
  }
}

// ---------------------------------------------------------------- the Library

const KIND_BY_EXT = { '.zip': 'project', '.pdf': 'document', '.xlsx': 'spreadsheet', '.csv': 'spreadsheet', '.html': 'page', '.htm': 'page', '.md': 'text', '.txt': 'text', '.json': 'text' };
/** Everything in the Atlas Bot folders, newest first, with what made it (index) where known. */
function library() {
  const idx = new Map(readIndex().map((x) => [path.resolve(x.file), x]));
  const out = [];
  let dirs = [];
  try { dirs = fs.readdirSync(base(), { withFileTypes: true }).filter((d) => d.isDirectory()); } catch { return []; }
  for (const d of dirs) {
    const dir = path.join(base(), d.name);
    for (const f of listFiles(dir)) {
      const file = path.join(dir, f.name);
      const i = idx.get(path.resolve(file));
      // a document's Markdown and a spreadsheet's CSV twin sit beside the main file: shown with it, not as their own rows
      const ext = path.extname(f.name).toLowerCase();
      const twin = (ext === '.md' && fs.existsSync(file.replace(/\.md$/i, '.pdf'))) || (ext === '.csv' && fs.existsSync(file.replace(/\.csv$/i, '.xlsx')));
      if (twin && !i) continue;
      out.push({ file, name: f.name, title: i ? i.title : f.name, kind: i ? i.kind : (KIND_BY_EXT[ext] || 'download'), made: !!i,
        job: i ? i.job : null, goal: i ? i.goal : d.name.replace(/\s*\([\w-]{1,6}\)$/, ''), at: i ? i.at : f.at, size: f.size });
    }
  }
  return out.sort((a, b) => b.at - a.at);
}
function open(file) {
  if (!inside(file) || !fs.existsSync(file)) return false;
  if (/\.html?$/i.test(file)) { openPage(file); return true; }
  shell.openPath(file); return true;
}
function showInFolder(file) { if (!inside(file) || !fs.existsSync(file)) return false; shell.showItemInFolder(file); return true; }
function remove(file) {
  if (!inside(file)) return false;
  try { fs.rmSync(file, { force: true }); } catch { return false; }
  writeIndex(readIndex().filter((x) => path.resolve(x.file) !== path.resolve(file)));
  return true;
}

// >>> attachments: files sent in the chat are kept in the Library (Documents/Atlas Bot/Uploads)
function keepUpload(file, title) { remember({ file, title, kind: 'file', job: null, goal: 'Sent in the chat', at: Date.now() }); }
// <<< attachments
// >>> projects (projects.js): a finished project's zip goes in the Library, under Documents/Atlas Bot/Projects
function saveProjectZip(projectName, buf) {
  const dir = path.join(base(), 'Projects');
  fs.mkdirSync(dir, { recursive: true });
  const f = freshPath(dir, fileName(projectName, '.zip').replace(/\.[^.]+$/, '') + '.zip');
  fs.writeFileSync(f, buf);
  remember({ file: f, title: projectName, kind: 'project', job: null, goal: 'Projects', at: Date.now() });
  return { file: f, name: path.basename(f) };
}
// <<< projects

module.exports = { keepUpload, saveProjectZip, run, library, open, showInFolder, remove, folderFor, fileName, freshPath, inside, cleanSpec, documentHtml, pageFromSpec, NAMES: ['workspace_list', 'workspace_read', 'workspace_write', 'make_document', 'make_spreadsheet', 'make_page'] };

// Email on the PC: Atlas reads, searches, drafts and sends the user's email over IMAP and SMTP, signed in with an app
// password (the way Gmail, Yahoo, iCloud, AOL, Zoho and Fastmail let a personal app in without a registered sign-in
// app). Outlook.com and Proton don't allow that any more, so for them Atlas reads mail in its bot browser instead.
//
// - The password is encrypted with Windows' own protection for this user (safeStorage), kept here, never synced and
//   never given to the page or the model.
// - Lists fetch headers only; a message's body is fetched when it's read. One connection is kept open for a minute or
//   so between uses, then closed. Everything has a time limit.
// - Sending and deleting are decided by the caller (renderer/mail.js asks the user first); drafts live here until sent.
'use strict';
const T = require('./mailtext');

const OP_MS = 45_000;            // one operation, all in
const IDLE_MS = 90_000;          // close the connection after this long unused
const LIST_MAX = 50;
const BODY_MAX = 12_000;         // characters of a message given to the model
const ATTACH_MAX = 25 * 1024 * 1024;

function timeout(p, ms, what) {
  let t; return Promise.race([p, new Promise((_, no) => { t = setTimeout(() => no(Object.assign(new Error(`${what} took too long`), { code: 'ETIMEDOUT' })), ms); })]).finally(() => clearTimeout(t));
}

/**
 * deps: { load(): text|null, save(text), encrypt(text): string, decrypt(string): text, attachmentsDir(): path,
 *         imapOptions?: extra ImapFlow options (tests), smtpOptions?: extra nodemailer options (tests), now?() }
 */
function createMail(deps) {
  const { ImapFlow } = require('imapflow');
  const { simpleParser } = require('mailparser');
  const nodemailer = require('nodemailer');
  const fs = require('fs'); const path = require('path');
  const now = deps.now || (() => Date.now());

  let account = null;           // { email, name, imap, smtp, user, pass (encrypted), provider, webmail }
  try { const a = JSON.parse(deps.load() || 'null'); if (a && a.email) account = a; } catch {}
  let client = null, clientReady = null, idleTimer = null, folders = null;
  let chain = Promise.resolve();          // one operation at a time on the connection
  const drafts = new Map(); let draftN = 0;
  const parsed = new Map();               // the last few messages read, by id (for attachments and replies)
  let unread = { n: null, at: 0 };

  const preset = () => (account ? { ...T.presetFor(account.email), ...(account.provider ? { name: account.providerName || T.presetFor(account.email).name } : {}) } : null);
  function publicAccount() {
    if (!account) return null;
    const { pass, ...rest } = account; return { ...rest, hasPassword: !!pass };
  }

  // ---------------------------------------------------------------- the connection

  async function close() {
    clearTimeout(idleTimer); idleTimer = null; folders = null;
    const c = client; client = null; clientReady = null;
    if (c) { try { await timeout(c.logout(), 5000, 'Signing out'); } catch { try { c.close(); } catch {} } }
  }
  function touch() { clearTimeout(idleTimer); idleTimer = setTimeout(() => { close(); }, IDLE_MS); if (idleTimer.unref) idleTimer.unref(); }

  async function connect() {
    if (!account || account.webmail) throw new Error('No email account is set up for Atlas.');
    if (client && client.usable) return client;
    if (clientReady) return clientReady;
    const c = new ImapFlow({
      host: account.imap.host, port: account.imap.port, secure: account.imap.secure,
      auth: { user: account.user || account.email, pass: deps.decrypt(account.pass) },
      logger: false, connectionTimeout: 15_000, greetingTimeout: 15_000, socketTimeout: 90_000, disableAutoIdle: true,
      clientInfo: { name: 'Atlas' }, ...(deps.imapOptions || {}),
    });
    c.on('error', () => {});            // a dropped connection: the next use connects again
    c.on('close', () => { if (client === c) { client = null; folders = null; } });
    clientReady = (async () => {
      try { await timeout(c.connect(), 30_000, 'Connecting to the mail server'); client = c; return c; }
      finally { clientReady = null; }
    })();
    return clientReady;
  }

  /** Runs [fn] with the connection, one at a time, with a time limit; reconnects once if the connection had died. */
  function withClient(fn) {
    const run = async () => {
      let lastErr;
      for (let attempt = 0; attempt < 2; attempt++) {
        try { const c = await connect(); const r = await timeout(fn(c), OP_MS, 'The mail server'); touch(); return r; }
        catch (e) {
          lastErr = e;
          const dead = !client || /closed|not available|ECONNRESET|EPIPE|socket/i.test(String(e && (e.message || e.code)));
          if (e && (e.authenticationFailed || /AUTHENTICATIONFAILED|Invalid credentials/i.test(String(e.responseText || e.message)))) break;
          if (!dead || attempt) break;
          await close();
        }
      }
      throw lastErr;
    };
    const p = chain.then(run, run); chain = p.catch(() => {}); return p;
  }

  // ---------------------------------------------------------------- folders

  const ALIASES = { inbox: null, sent: '\\Sent', trash: '\\Trash', bin: '\\Trash', deleted: '\\Trash', archive: '\\Archive', all: '\\All', 'all mail': '\\All', drafts: '\\Drafts', spam: '\\Junk', junk: '\\Junk', starred: '\\Flagged', flagged: '\\Flagged', important: '\\Important' };
  async function folderList(c) {
    if (folders) return folders;
    const list = await c.list();
    folders = list.filter((f) => !(f.flags && (f.flags.has ? f.flags.has('\\Noselect') : [...(f.flags || [])].includes('\\Noselect')))).map((f) => ({ path: f.path, special: f.specialUse || null }));
    return folders;
  }
  /** "inbox", "sent", "trash", "archive", "spam", a folder's own name: its path on the server. */
  async function resolveFolder(c, name) {
    const n = String(name || 'INBOX').trim(); if (!n || /^inbox$/i.test(n)) return 'INBOX';
    const list = await folderList(c);
    const exact = list.find((f) => f.path === n) || list.find((f) => f.path.toLowerCase() === n.toLowerCase());
    if (exact) return exact.path;
    const sp = ALIASES[n.toLowerCase()];
    if (sp) { const f = list.find((x) => x.special === sp); if (f) return f.path; }
    const tail = list.find((f) => f.path.toLowerCase().split(/[/.]/).pop() === n.toLowerCase()); if (tail) return tail.path;
    throw Object.assign(new Error(`There's no folder called "${n}". Folders: ${list.map((f) => f.path).join(', ')}`), { plain: true });
  }
  async function specialFolder(c, special, fallback) {
    const list = await folderList(c); const f = list.find((x) => x.special === special);
    if (f) return f.path;
    if (fallback) { const g = list.find((x) => x.path.toLowerCase() === fallback.toLowerCase()); if (g) return g.path; try { await c.mailboxCreate(fallback); folders = null; return fallback; } catch {} }
    return null;
  }
  async function inFolder(c, folder, fn) {
    const lock = await c.getMailboxLock(folder);
    try { return await fn(); } finally { lock.release(); }
  }

  // ---------------------------------------------------------------- reading

  function summary(folder, m) {
    const e = m.envelope || {};
    const flags = m.flags || new Set();
    return {
      id: T.makeId(folder, m.uid), uid: m.uid, date: e.date || m.internalDate || null,
      from: (e.from || []).map(T.addr).join(', '), to: (e.to || []).map(T.addr).join(', '), subject: e.subject || '',
      unread: !flags.has('\\Seen'), starred: flags.has('\\Flagged'), messageId: e.messageId || null,
    };
  }
  function criteria(c, q, unreadOnly) {
    const out = {};
    if (q && c.capabilities && c.capabilities.has('X-GM-EXT-1')) out.gmraw = q + (unreadOnly && !/is:unread/i.test(q) ? ' is:unread' : '');
    else if (q) {
      const p = T.parseQuery(q);
      if (p.from) out.from = p.from; if (p.to) out.to = p.to; if (p.cc) out.cc = p.cc; if (p.subject) out.subject = p.subject;
      if (p.unread === true) out.seen = false; if (p.unread === false) out.seen = true; if (p.starred) out.flagged = true;
      if (p.since) out.since = new Date(p.since + 'T00:00:00Z'); if (p.before) out.before = new Date(p.before + 'T00:00:00Z');
      if (p.text) out.or = [{ subject: p.text }, { from: p.text }, { body: p.text }];
    }
    if (unreadOnly && !out.gmraw) out.seen = false;
    return Object.keys(out).length ? out : { all: true };
  }

  async function list({ folder, unread_only, query, limit } = {}) {
    const n = Math.max(1, Math.min(LIST_MAX, Number(limit) || 15));
    return withClient(async (c) => {
      const path = await resolveFolder(c, folder);
      return inFolder(c, path, async () => {
        const uids = await c.search(criteria(c, query, !!unread_only), { uid: true }) || [];
        const pick = uids.sort((a, b) => a - b).slice(-n);
        const out = [];
        if (pick.length) for await (const m of c.fetch(pick.join(','), { uid: true, envelope: true, flags: true, internalDate: true }, { uid: true })) out.push(summary(path, m));
        out.sort((a, b) => b.uid - a.uid);
        if (path === 'INBOX' && !query && !unread_only) unread = { n: null, at: 0 };   // read again next time
        return { folder: path, total: uids.length, messages: out };
      });
    });
  }

  async function fetchParsed(id) {
    const p = T.parseId(id); if (!p) throw Object.assign(new Error(`"${id}" isn't an email id (they look like INBOX#1234; get them from email_list).`), { plain: true });
    const key = T.makeId(p.folder, p.uid);
    if (parsed.has(key)) return parsed.get(key);
    const got = await withClient(async (c) => inFolder(c, p.folder, async () => {
      const m = await c.fetchOne(String(p.uid), { uid: true, source: true, flags: true, envelope: true }, { uid: true });
      if (!m) return null;
      return { m, mail: await simpleParser(m.source, { skipImageLinks: true, skipTextToHtml: true }) };
    }));
    if (!got) throw Object.assign(new Error(`That email (${id}) isn't there any more: it may have been moved or deleted.`), { plain: true });
    const entry = { id: key, folder: p.folder, uid: p.uid, flags: got.m.flags || new Set(), mail: got.mail };
    parsed.set(key, entry); while (parsed.size > 8) parsed.delete(parsed.keys().next().value);
    return entry;
  }
  /** "Anna Smith <anna@x.org>, b@y.com" from a parsed address header (no quotes around names). */
  const people = (h) => (h ? [].concat(h).flatMap((x) => x.value || []).map(T.addr).join(', ') : '');
  function bodyText(mail) {
    const t = mail.text && mail.text.trim() ? mail.text : mail.html ? T.htmlToText(mail.html) : '';
    return t.replace(/\r/g, '');
  }

  async function read({ id, full } = {}) {
    const e = await fetchParsed(id); const mail = e.mail;
    const raw = bodyText(mail);
    const s = full ? { text: raw.trim(), hidden: false } : T.stripQuoted(raw);
    let body = s.text; let cut = false;
    if (body.length > BODY_MAX) { body = body.slice(0, BODY_MAX); cut = true; }
    const att = (mail.attachments || []).filter((a) => !a.related);
    return {
      id: e.id, from: people(mail.from), to: people(mail.to), cc: people(mail.cc),
      date: mail.date ? mail.date.toISOString() : null, subject: mail.subject || '', unread: !e.flags.has('\\Seen'),
      body, quotedHidden: s.hidden, cut,
      attachments: att.map((a, i) => ({ index: i + 1, name: a.filename || `attachment-${i + 1}`, type: a.contentType, size: a.size })),
    };
  }

  async function saveAttachment({ id, index } = {}) {
    const e = await fetchParsed(id);
    const att = (e.mail.attachments || []).filter((a) => !a.related);
    const a = att[(Number(index) || 1) - 1];
    if (!a) throw Object.assign(new Error(`That email has ${att.length} attachment${att.length === 1 ? '' : 's'}; there's no number ${index}.`), { plain: true });
    if (a.size > ATTACH_MAX) throw Object.assign(new Error(`That attachment is ${Math.round(a.size / 1048576)} MB, too big to save from here (limit 25 MB).`), { plain: true });
    const dir = deps.attachmentsDir(); fs.mkdirSync(dir, { recursive: true });
    const name = String(a.filename || `attachment-${index}`).replace(/[\\/:*?"<>|\x00-\x1f]+/g, '_').replace(/^\.+/, '').slice(0, 120) || 'attachment';
    let file = path.join(dir, name); const ext = path.extname(name), base = name.slice(0, name.length - ext.length);
    for (let i = 2; fs.existsSync(file) && i < 1000; i++) file = path.join(dir, `${base} (${i})${ext}`);
    if (path.dirname(path.resolve(file)) !== path.resolve(dir)) throw new Error('bad name');
    fs.writeFileSync(file, a.content);
    return { file, name: path.basename(file), size: a.size };
  }

  // ---------------------------------------------------------------- changing things

  async function setFlags({ ids, read: isRead, starred } = {}) {
    const list = T.parseIds(ids); if (!list.length) throw Object.assign(new Error('Give the email ids (from email_list).'), { plain: true });
    return withClient(async (c) => {
      for (const [folder, uids] of group(list)) await inFolder(c, folder, async () => {
        const set = uids.join(',');
        if (isRead === true) await c.messageFlagsAdd(set, ['\\Seen'], { uid: true });
        if (isRead === false) await c.messageFlagsRemove(set, ['\\Seen'], { uid: true });
        if (starred === true) await c.messageFlagsAdd(set, ['\\Flagged'], { uid: true });
        if (starred === false) await c.messageFlagsRemove(set, ['\\Flagged'], { uid: true });
      });
      for (const p of list) parsed.delete(T.makeId(p.folder, p.uid));
      unread = { n: null, at: 0 };
      return list.length;
    });
  }
  function group(list) { const m = new Map(); for (const p of list) { if (!m.has(p.folder)) m.set(p.folder, []); m.get(p.folder).push(p.uid); } return m; }

  async function moveTo({ ids, folder, special, fallback } = {}) {
    const list = T.parseIds(ids); if (!list.length) throw Object.assign(new Error('Give the email ids (from email_list).'), { plain: true });
    return withClient(async (c) => {
      const dest = special ? await specialFolder(c, special, fallback) : await resolveFolder(c, folder);
      if (!dest) return { moved: 0, dest: null };
      let moved = 0;
      for (const [from, uids] of group(list)) {
        if (from === dest) continue;
        await inFolder(c, from, async () => { await c.messageMove(uids.join(','), dest, { uid: true }); });
        moved += uids.length;
      }
      for (const p of list) parsed.delete(T.makeId(p.folder, p.uid));
      unread = { n: null, at: 0 };
      return { moved, dest };
    });
  }
  async function archive({ ids } = {}) {
    // Gmail: archiving is taking it out of the inbox, into All Mail; elsewhere the Archive folder (made if missing)
    const r = await withClient(async (c) => (await folderList(c)).some((f) => f.special === '\\All'));
    return r ? moveTo({ ids, special: '\\All' }) : moveTo({ ids, special: '\\Archive', fallback: 'Archive' });
  }
  async function remove({ ids } = {}) {
    const r = await moveTo({ ids, special: '\\Trash', fallback: 'Trash' });
    return r;
  }

  // ---------------------------------------------------------------- drafts and sending

  async function draft({ to, cc, subject, body, reply_to } = {}) {
    let orig = null;
    if (reply_to) { const e = await fetchParsed(reply_to); orig = e; }
    const toList = T.splitAddresses(to || (orig ? people(orig.mail.replyTo || orig.mail.from) : ''));
    if (!toList || !toList.length) throw Object.assign(new Error(`"${to}" isn't a valid email address. If you only have a name, look it up first (find_contact, or ask the user).`), { plain: true });
    const ccList = cc ? T.splitAddresses(cc) : [];
    if (cc && !ccList) throw Object.assign(new Error(`"${cc}" isn't a valid email address.`), { plain: true });
    const d = {
      id: 'd' + (++draftN), to: toList.join(', '), cc: (ccList || []).join(', '),
      subject: orig ? T.replySubject(subject || orig.mail.subject) : String(subject || '').trim() || '(no subject)',
      body: orig ? T.quoteForReply(body, { date: orig.mail.date, from: people(orig.mail.from), text: T.stripQuoted(bodyText(orig.mail)).text.slice(0, 4000) }) : String(body || '').trim() + '\n',
      inReplyTo: orig ? orig.mail.messageId || null : null,
      references: orig ? [].concat(orig.mail.references || [], orig.mail.messageId ? [orig.mail.messageId] : []).slice(-10) : [],
      replyOf: orig ? orig.id : null, at: now(),
    };
    drafts.set(d.id, d); while (drafts.size > 20) drafts.delete(drafts.keys().next().value);
    return d;
  }
  function getDraft(id) { const d = drafts.get(String(id || '').trim()); return d ? { ...d } : null; }

  async function send({ draft_id } = {}) {
    const d = drafts.get(String(draft_id || '').trim());
    if (!d) throw Object.assign(new Error(`There's no draft "${draft_id}" (drafts are kept until Atlas restarts). Make it again with email_draft.`), { plain: true });
    const t = nodemailer.createTransport({
      host: account.smtp.host, port: account.smtp.port, secure: account.smtp.secure, requireTLS: !account.smtp.secure && !(deps.smtpOptions && deps.smtpOptions.ignoreTLS),
      auth: { user: account.user || account.email, pass: deps.decrypt(account.pass) },
      connectionTimeout: 15_000, greetingTimeout: 15_000, socketTimeout: 60_000, ...(deps.smtpOptions || {}),
    });
    try {
      const info = await timeout(t.sendMail({
        from: account.name ? { name: account.name, address: account.email } : account.email, to: d.to, cc: d.cc || undefined, subject: d.subject, text: d.body,
        inReplyTo: d.inReplyTo || undefined, references: d.references.length ? d.references : undefined,
      }), OP_MS, 'Sending');
      drafts.delete(d.id);
      if (d.replyOf) { const p = T.parseId(d.replyOf); if (p) withClient((c) => inFolder(c, p.folder, () => c.messageFlagsAdd(String(p.uid), ['\\Answered'], { uid: true }))).catch(() => {}); }
      return { to: d.to, subject: d.subject, messageId: info.messageId || null, accepted: (info.accepted || []).length };
    } finally { try { t.close(); } catch {} }
  }

  async function unreadCount({ fresh } = {}) {
    if (!account || account.webmail) return null;
    if (!fresh && unread.n !== null && now() - unread.at < 5 * 60_000) return unread.n;
    const n = await withClient(async (c) => { const s = await c.status('INBOX', { unseen: true }); return s.unseen; });
    unread = { n, at: now() }; return n;
  }

  // ---------------------------------------------------------------- the account

  async function setup({ email, password, name, imapHost, imapPort, smtpHost, smtpPort, user } = {}) {
    const addr = String(email || '').trim();
    if (!T.validEmail(addr)) return { error: "That isn't an email address." };
    const p = T.presetFor(addr);
    await close(); drafts.clear(); parsed.clear(); unread = { n: null, at: 0 };
    if (p.webmail) {
      account = { email: addr, name: String(name || '').trim().slice(0, 60), provider: p.id, providerName: p.name, webmail: p.webmail };
      deps.save(JSON.stringify(account));
      return { ok: true, webmail: p.webmail, note: p.help, account: publicAccount() };
    }
    if (!password) return { error: 'Paste the app password.' };
    const imap = { host: String(imapHost || p.imap.host).trim(), port: Number(imapPort) || p.imap.port, secure: (Number(imapPort) || p.imap.port) === 993 };
    const smtp = { host: String(smtpHost || p.smtp.host).trim(), port: Number(smtpPort) || p.smtp.port, secure: (Number(smtpPort) || p.smtp.port) === 465 };
    if (deps.forceSecure !== undefined) { imap.secure = deps.forceSecure; smtp.secure = deps.forceSecure; }
    const next = { email: addr, name: String(name || '').trim().slice(0, 60), user: String(user || '').trim() || addr, provider: p.id, providerName: p.name,
      imap, smtp, pass: deps.encrypt(p.id === 'gmail' ? String(password).replace(/\s+/g, '') : String(password).trim()) };   // Google shows its app passwords in groups of four
    const old = account; account = next;
    try {
      const n = await withClient(async (c) => { const s = await c.status('INBOX', { unseen: true }); return s.unseen; });
      unread = { n, at: now() };
      deps.save(JSON.stringify(account));
      return { ok: true, unread: n, account: publicAccount() };
    } catch (e) {
      await close(); account = old;
      return { error: e.plain ? e.message : T.friendlyError(e, p) };
    }
  }
  async function forget() { await close(); account = null; drafts.clear(); parsed.clear(); unread = { n: null, at: 0 }; deps.save('null'); return true; }

  /** For the app: run an operation, errors turned into plain words. */
  async function op(name, args = {}) {
    try {
      switch (name) {
        case 'status': return { account: publicAccount(), unread: unread.n };
        case 'setup': return await setup(args);
        case 'forget': return { ok: await forget() };
        case 'list': return { ok: await list(args) };
        case 'read': return { ok: await read(args) };
        case 'saveAttachment': return { ok: await saveAttachment(args) };
        case 'flags': return { ok: await setFlags(args) };
        case 'archive': return { ok: await archive(args) };
        case 'move': return { ok: await moveTo(args) };
        case 'delete': return { ok: await remove(args) };
        case 'draft': return { ok: await draft(args) };
        case 'getDraft': return { ok: getDraft(args.id) };
        case 'send': return { ok: await send(args) };
        case 'unread': return { ok: await unreadCount(args) };
        default: return { error: 'unknown email operation' };
      }
    } catch (e) {
      return { error: e && e.plain ? e.message : T.friendlyError(e, preset()) };
    }
  }

  return { op, close, account: publicAccount };
}

module.exports = { createMail };

// Email, the plain part: which servers a mail address uses, turning HTML into readable text, hiding the quoted history
// under a reply, quoting for a reply, reading a search like "from:anna is:unread", and saying what went wrong in plain
// words. No network here, so all of it is tested in Node (test/logic.test.mjs) and the phone's MailText.kt follows the
// same rules (tools/mail-fixtures.json holds the shared cases).
'use strict';

// ---------------------------------------------------------------- which servers

/**
 * Known providers by address domain. `webmail`: the provider no longer lets apps sign in with a password over IMAP
 * (Outlook.com turned it off in September 2024; Proton needs its Bridge app), so Atlas reads it in its bot browser.
 */
const PROVIDERS = [
  { id: 'gmail', name: 'Gmail', domains: ['gmail.com', 'googlemail.com'], imap: ['imap.gmail.com', 993, true], smtp: ['smtp.gmail.com', 465, true],
    help: 'Gmail needs an app password, not your normal password: turn on 2-Step Verification, then make one at https://myaccount.google.com/apppasswords and paste its 16 letters here.' },
  { id: 'yahoo', name: 'Yahoo Mail', domains: ['yahoo.com', 'ymail.com', 'rocketmail.com', 'yahoo.co.uk', 'yahoo.fr'], imap: ['imap.mail.yahoo.com', 993, true], smtp: ['smtp.mail.yahoo.com', 465, true],
    help: 'Yahoo needs an app password: Yahoo Account Security → Generate app password, then paste it here.' },
  { id: 'icloud', name: 'iCloud Mail', domains: ['icloud.com', 'me.com', 'mac.com'], imap: ['imap.mail.me.com', 993, true], smtp: ['smtp.mail.me.com', 587, false],
    help: 'iCloud needs an app-specific password: account.apple.com → Sign-In and Security → App-Specific Passwords.' },
  { id: 'aol', name: 'AOL Mail', domains: ['aol.com'], imap: ['imap.aol.com', 993, true], smtp: ['smtp.aol.com', 465, true],
    help: 'AOL needs an app password: Account Security → Generate app password.' },
  { id: 'zoho', name: 'Zoho Mail', domains: ['zoho.com', 'zohomail.com'], imap: ['imap.zoho.com', 993, true], smtp: ['smtp.zoho.com', 465, true],
    help: 'With two-factor sign-in on, Zoho needs an app-specific password (Zoho Accounts → Security → App Passwords).' },
  { id: 'fastmail', name: 'Fastmail', domains: ['fastmail.com', 'fastmail.fm'], imap: ['imap.fastmail.com', 993, true], smtp: ['smtp.fastmail.com', 465, true],
    help: 'Fastmail needs an app password: Settings → Privacy & Security → App passwords.' },
  { id: 'gmx', name: 'GMX', domains: ['gmx.com', 'gmx.net', 'gmx.de'], imap: ['imap.gmx.com', 993, true], smtp: ['mail.gmx.com', 587, false],
    help: 'In GMX settings, allow access through POP3 and IMAP first.' },
  { id: 'outlook', name: 'Outlook.com', domains: ['outlook.com', 'hotmail.com', 'live.com', 'msn.com', 'outlook.co.uk', 'hotmail.co.uk'],
    webmail: 'https://outlook.live.com/mail/', help: 'Outlook.com stopped letting apps sign in with a password (September 2024), so Atlas reads it in its own browser instead: you sign in there once.' },
  { id: 'proton', name: 'Proton Mail', domains: ['proton.me', 'protonmail.com', 'pm.me'],
    webmail: 'https://mail.proton.me/', help: 'Proton Mail only allows other apps through its paid Bridge app, so Atlas reads it in its own browser instead: you sign in there once.' },
];

function domainOf(email) { const m = String(email || '').trim().toLowerCase().match(/@([^@\s]+)$/); return m ? m[1] : ''; }

/** The servers for [email]: a known provider, or a guess (imap.<domain> / smtp.<domain>) the user can change. */
function presetFor(email) {
  const d = domainOf(email);
  const p = PROVIDERS.find((x) => x.domains.includes(d));
  if (p && p.webmail) return { id: p.id, name: p.name, webmail: p.webmail, help: p.help, known: true };
  if (p) return { id: p.id, name: p.name, imap: { host: p.imap[0], port: p.imap[1], secure: p.imap[2] }, smtp: { host: p.smtp[0], port: p.smtp[1], secure: p.smtp[2] }, help: p.help, known: true };
  return { id: 'other', name: d || 'Email', imap: { host: d ? 'imap.' + d : '', port: 993, secure: true }, smtp: { host: d ? 'smtp.' + d : '', port: 465, secure: true },
    help: 'If your provider uses two-step sign-in, it probably needs an app password rather than your normal one.', known: false };
}

function validEmail(s) { return /^[^\s@<>(),;:"]+@[^\s@<>(),;:"]+\.[^\s@<>(),;:"]+$/.test(String(s || '').trim()); }
/** "Anna <a@x.com>, b@y.com" → ['Anna <a@x.com>', 'b@y.com']; null when one of them isn't an address. */
function splitAddresses(s) {
  const parts = String(s || '').split(/[,;]\s*(?=(?:[^"]*"[^"]*")*[^"]*$)/).map((x) => x.trim()).filter(Boolean);
  for (const p of parts) { const m = p.match(/<([^>]+)>\s*$/); if (!validEmail(m ? m[1] : p)) return null; }
  return parts;
}

// ---------------------------------------------------------------- HTML → text

const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ndash: '–', mdash: '—', hellip: '…', rsquo: '’', lsquo: '‘', rdquo: '”', ldquo: '“', copy: '©', reg: '®', trade: '™', bull: '•', middot: '·', euro: '€', pound: '£',
  eacute: 'é', egrave: 'è', ecirc: 'ê', euml: 'ë', aacute: 'á', agrave: 'à', acirc: 'â', auml: 'ä', aring: 'å', oacute: 'ó', ograve: 'ò', ocirc: 'ô', ouml: 'ö', oslash: 'ø', iacute: 'í', igrave: 'ì', iuml: 'ï', uacute: 'ú', ugrave: 'ù', uuml: 'ü', ntilde: 'ñ', ccedil: 'ç', szlig: 'ß', Eacute: 'É', Agrave: 'À', Auml: 'Ä', Ouml: 'Ö', Uuml: 'Ü' };
function decodeEntities(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') { const n = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10); return n > 0 && n <= 0x10ffff ? String.fromCodePoint(n) : ''; }
    const v = ENT[e] !== undefined ? ENT[e] : ENT[e.toLowerCase()]; return v === undefined ? m : v;
  });
}
/** Readable text from an email's HTML: no styles or scripts, paragraphs and lists kept, links as "text (url)". */
function htmlToText(html) {
  let s = String(html || '');
  s = s.replace(/<!--[\s\S]*?-->/g, '').replace(/<(script|style|head|title)\b[\s\S]*?<\/\1\s*>/gi, '');
  s = s.replace(/<a\b[^>]*?href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a\s*>/gi, (m, href, inner) => {
    const t = inner.replace(/<[^>]+>/g, '').trim(); const u = decodeEntities(href.trim());
    if (!t) return ''; if (/^mailto:/i.test(u) || t === u || !/^https?:/i.test(u)) return t; return `${t} (${u})`;
  });
  s = s.replace(/<br\s*\/?>/gi, '\n').replace(/<li\b[^>]*>/gi, '\n• ').replace(/<\/(p|div|h[1-6]|tr|table|ul|ol|blockquote)\s*>/gi, '\n').replace(/<(p|div|h[1-6]|tr|table|ul|ol|blockquote)\b[^>]*>/gi, '\n').replace(/<\/t[dh]\s*>/gi, '\t');
  s = s.replace(/<[^>]+>/g, '');
  s = decodeEntities(s).replace(/ /g, ' ').replace(/\r/g, '');
  s = s.split('\n').map((l) => l.replace(/[ \t]+/g, ' ').trim()).join('\n');
  return s.replace(/\n{3,}/g, '\n\n').trim();
}

// ---------------------------------------------------------------- the quoted history under a reply

const QUOTE_HEADS = [
  /^On .{4,200}(wrote|écrit|schrieb|escribió):\s*$/i,
  /^-{2,}\s*(Original Message|Forwarded message|Mensaje original|Message d'origine)\s*-{2,}\s*$/i,
  /^_{5,}\s*$/,
  /^From:\s.+$/i,
];
/**
 * The new part of a message, without the quoted history under it ("On … wrote:", "> …", "-----Original Message-----",
 * an Outlook "From:" block). Returns { text, hidden } — hidden: some history was left out. A message that is only
 * quotes (a forward) is kept whole.
