const TEXT_EXT = new Set(['txt', 'md', 'markdown', 'csv', 'tsv', 'json', 'xml', 'yaml', 'yml', 'html', 'htm', 'log', 'ini', 'toml', 'kt', 'kts', 'java', 'py', 'js', 'ts', 'tsx', 'jsx', 'c', 'h', 'cpp', 'cs', 'go', 'rs', 'rb', 'php', 'swift', 'sh', 'ps1', 'bat', 'sql', 'lua', 'dart', 'css']);
const IMG = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', gif: 'image/gif' };
const VID = { mp4: 'video/mp4', webm: 'video/webm', mov: 'video/quicktime' };
const TEXT_MAX = 120000;

/** The words in a Word (.docx) file: reads its document.xml straight out of the zip. */
function docxText(buf) {
  // find the central directory, then the entry "word/document.xml"
  let eocd = -1;
  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 65557); i--) if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
  if (eocd < 0) throw new Error('not a Word file');
  const count = buf.readUInt16LE(eocd + 10); let off = buf.readUInt32LE(eocd + 16);
  for (let n = 0; n < count; n++) {
    const method = buf.readUInt16LE(off + 10), csize = buf.readUInt32LE(off + 20);
    const nlen = buf.readUInt16LE(off + 28), xlen = buf.readUInt16LE(off + 30), clen = buf.readUInt16LE(off + 32), local = buf.readUInt32LE(off + 42);
    const name = buf.toString('utf8', off + 46, off + 46 + nlen);
    if (name === 'word/document.xml') {
      const lnl = buf.readUInt16LE(local + 26), lxl = buf.readUInt16LE(local + 28);
      const data = buf.subarray(local + 30 + lnl + lxl, local + 30 + lnl + lxl + csize);
      const xml = (method === 8 ? zlib.inflateRawSync(data) : data).toString('utf8');
      return xml.replace(/<\/w:p>/g, '\n').replace(/<w:tab\/>/g, '\t').replace(/<[^>]+>/g, '')
        .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'")
        .split('\n').map((l) => l.trimEnd()).join('\n').replace(/\n{3,}/g, '\n\n').trim();
    }
    off += 46 + nlen + xlen + clen;
  }
  return '';
}

/** A file as an attachment: {kind: image|video|pdf|text, mime, name, base64 | text}. Throws past the limits. */
function loadAttachment(p) {
  const { nativeImage } = require('electron');
  const name = path.basename(p), ext = path.extname(p).slice(1).toLowerCase();
  const size = fs.statSync(p).size;
  if (IMG[ext]) {
    // pictures are shrunk to at most 1600 px and sent as JPEG (quick, accepted everywhere)
    let img = nativeImage.createFromPath(p);
    if (img.isEmpty()) throw new Error(`Couldn't open “${name}”.`);
    const { width, height } = img.getSize(); const s = Math.min(1, 1600 / Math.max(width, height));
    if (s < 1) img = img.resize({ width: Math.round(width * s), height: Math.round(height * s), quality: 'best' });
    return { kind: 'image', mime: 'image/jpeg', name, base64: img.toJPEG(85).toString('base64') };
  }
  if (VID[ext]) {
    if (size > 15 * 1024 * 1024) throw new Error(`“${name}” is ${Math.round(size / 1048576)} MB; videos can be up to 15 MB.`);
    return { kind: 'video', mime: VID[ext], name, base64: fs.readFileSync(p).toString('base64') };
  }
  if (size > 10 * 1024 * 1024) throw new Error(`“${name}” is ${Math.round(size / 1048576)} MB; files can be up to 10 MB.`);
  if (ext === 'pdf') return { kind: 'pdf', mime: 'application/pdf', name, base64: fs.readFileSync(p).toString('base64') };
  let text;
  if (ext === 'docx') text = docxText(fs.readFileSync(p));
  else if (TEXT_EXT.has(ext)) text = fs.readFileSync(p, 'utf8');
  else throw new Error(`Atlas can take pictures, videos, PDFs, text files and Word documents. “${name}” is none of those.`);
  if (!text.trim()) throw new Error(`“${name}” has no text I can read.`);
  if (text.length > TEXT_MAX) text = text.slice(0, TEXT_MAX) + '\n…(the rest of the file was cut: it\'s very long)';
  return { kind: 'text', mime: 'text/plain', name, text };
}

// The user's own folders, where Windows really keeps them (OneDrive often moves Desktop and Documents).
const KNOWN = ['Desktop', 'Documents', 'Downloads', 'Pictures', 'Music', 'Videos'];
function knownFolder(k) {
  try { const { app } = require('electron'); if (app && app.getPath) return app.getPath(k.toLowerCase()); } catch {}
  return path.join(os.homedir(), k);
}
/** A path the model gave, as a full path: "~", "Desktop/notes.txt", "~/Documents/x" and bare names all start at the user's
 *  home or their real known folders, never at the app's own working folder (its install folder, or System32 at sign-in). */
function expand(p, folder = knownFolder) {
  let s = String(p || '').trim().replace(/^["']|["']$/g, '');
  s = s.replace(/%([^%]+)%/g, (_m, v) => process.env[v] || _m);
  if (/^~([\\/]|$)/.test(s)) s = s.replace(/^~[\\/]*/, '');
  else if (path.isAbsolute(s)) return path.resolve(s);
  const [first, ...rest] = s.split(/[\\/]+/);
  const k = KNOWN.find((n) => n.toLowerCase() === String(first).toLowerCase());
  if (k) return path.join(folder(k), ...rest);
  return path.resolve(os.homedir(), s);
}

// ------------------------------------------------------------------ the tools

async function run(name, a, e) {
  switch (name) {
    case 'open_app': {
      const n = String(a.name || '').trim();
      if (!n) return { error: 'Say which app.' };
      const r = await ps(`$a = Get-StartApps | Where-Object { $_.Name -like ${q('*' + n + '*')} } | Sort-Object { $_.Name.Length } | Select-Object -First 1
if ($a) { Start-Process ("shell:AppsFolder\\" + $a.AppID); "Opened " + $a.Name }
else { try { Start-Process ${q(n)} -ErrorAction Stop; "Opened " + ${q(n)} } catch { "NOTFOUND" } }`, 20000);
      if (r.code === -1) return { error: r.err };
      if (r.out.includes('NOTFOUND') || !r.out) return { error: `No app called “${n}” was found on this PC.` };
      return { out: r.out, step: r.out };
    }
    case 'list_apps': {
      const r = await ps(`Get-StartApps | Sort-Object Name | ForEach-Object { $_.Name }`, 20000);
      return r.code === -1 ? { error: r.err } : { out: 'Apps on this PC:\n' + r.out.split(/\r?\n/).slice(0, 400).join(', ') };
    }
    case 'open_link': { const u = String(a.url || ''); if (!/^(https?:|mailto:)/i.test(u)) return { error: 'Only web and email links.' }; await e.shell.openExternal(u); return { out: 'Opened ' + u, step: 'Opened ' + u.replace(/^https?:\/\//, '').slice(0, 50) }; }
    case 'open_path': { const p = expand(a.path); if (!fs.existsSync(p)) return { error: 'Nothing at ' + p }; const err = await e.shell.openPath(p); return err ? { error: err } : { out: 'Opened ' + p, step: 'Opened ' + path.basename(p) }; }
    case 'list_files': {
      const p = expand(a.path);
      const items = fs.readdirSync(p, { withFileTypes: true }).slice(0, 300).map((d) => {
        let info = ''; try { if (d.isFile()) { const st = fs.statSync(path.join(p, d.name)); info = ` (${Math.max(1, Math.round(st.size / 1024))} KB, ${st.mtime.toISOString().slice(0, 10)})`; } } catch {}
        return (d.isDirectory() ? '[folder] ' : '') + d.name + info;
      });
      return { out: `In ${p}:\n` + (items.join('\n') || '(empty)') };
    }
    case 'read_file': {
      const p = expand(a.path);
      const att = loadAttachment(p);
      if (att.kind !== 'text') return { error: `“${att.name}” isn't a text file; attach it to a message instead.` };
      return { out: `Contents of ${p}:\n${att.text}`, step: 'Read ' + path.basename(p) };
    }
    case 'write_file': {
      const p = expand(a.path);
      fs.mkdirSync(path.dirname(p), { recursive: true });
      fs.writeFileSync(p, String(a.text ?? ''), 'utf8');
      return { out: 'Saved ' + p, step: 'Saved ' + path.basename(p) };
    }
    case 'run_command': {
      const r = await ps(String(a.command || ''), Math.min(180, Math.max(5, num(a.timeout_s, 60))) * 1000);
      let out = (r.out || '') + (r.err ? '\n[errors]\n' + r.err : '');
      if (out.length > 8000) out = out.slice(0, 8000) + '\n…(cut)';
      return { out: `Exit code ${r.code}.\n${out || '(no output)'}`, step: 'Ran a command' };
    }
    case 'look_at_screen': {
      const d = e.screen.getPrimaryDisplay();
      const real = { w: Math.round(d.size.width * d.scaleFactor), h: Math.round(d.size.height * d.scaleFactor) };
      const s = Math.min(1, 1600 / real.w);
      const shotW = Math.round(real.w * s), shotH = Math.round(real.h * s);
      const src = await e.desktopCapturer.getSources({ types: ['screen'], thumbnailSize: { width: shotW, height: shotH } });
      if (!src.length) return { error: 'Couldn\'t capture the screen.' };
      // the primary screen (clicks are placed on it); with a second monitor it isn't always listed first
      const img = (src.find((x) => String(x.display_id) === String(d.id)) || src[0]).thumbnail;
      const sz = img.getSize();
      lastShot = { w: sz.width, h: sz.height, realW: real.w, realH: real.h };
      return { out: `Here is the screen (${sz.width}×${sz.height}). Give clicks in these coordinates.`, image: { mime: 'image/jpeg', base64: img.toJPEG(80).toString('base64') }, step: 'Looked at the screen' };
    }
    case 'click': {
      if (!lastShot) return { error: 'Look at the screen first (look_at_screen).' };
      const ax = num(a.x, NaN), ay = num(a.y, NaN);
      if (!Number.isFinite(ax) || !Number.isFinite(ay) || ax < 0 || ay < 0 || ax > lastShot.w || ay > lastShot.h) return { error: `Give x and y inside the screenshot (0-${lastShot.w}, 0-${lastShot.h}).` };
      const x = Math.round(ax * lastShot.realW / lastShot.w), y = Math.round(ay * lastShot.realH / lastShot.h);
      const [down, up] = a.button === 'right' ? [8, 16] : [2, 4];
      const times = a.double ? 2 : 1;
      const r = await ps(INPUT + `[void][AtlasInput]::SetCursorPos(${x}, ${y}); Start-Sleep -Milliseconds 60
for ($i = 0; $i -lt ${times}; $i++) { [AtlasInput]::mouse_event(${down}, 0, 0, 0, [UIntPtr]::Zero); [AtlasInput]::mouse_event(${up}, 0, 0, 0, [UIntPtr]::Zero); Start-Sleep -Milliseconds 80 }
"clicked"`, 15000);
      return r.code === -1 ? { error: r.err } : { out: `Clicked at ${a.x},${a.y}. Look at the screen again to see what happened.`, step: 'Clicked' };
    }
    case 'type_text': {
      const r = await ps(`Add-Type -AssemblyName System.Windows.Forms; [System.Windows.Forms.SendKeys]::SendWait(${q(sendKeysText(a.text || ''))}); "typed"`, 30000);
      return r.code === -1 ? { error: r.err } : { out: 'Typed it.', step: 'Typed' };
    }
    case 'press_keys': {
      let k; try { k = sendKeysCombo(a.keys || ''); } catch (err) { return { error: err.message }; }
      const r = await ps(`Add-Type -AssemblyName System.Windows.Forms; [System.Windows.Forms.SendKeys]::SendWait(${q(k)}); "pressed"`, 15000);
      return r.code === -1 ? { error: r.err } : { out: 'Pressed ' + a.keys + '.', step: 'Pressed ' + a.keys };
    }
    case 'scroll': {
      const amount = (a.direction === 'up' ? 1 : -1) * 120 * Math.min(20, Math.max(1, num(a.amount, 5)));
      const r = await ps(INPUT + `[AtlasInput]::mouse_event(0x0800, 0, 0, ${amount}, [UIntPtr]::Zero); "scrolled"`, 15000);
      return r.code === -1 ? { error: r.err } : { out: 'Scrolled ' + (a.direction || 'down') + '.', step: 'Scrolled' };
    }
    default: return { error: 'Unknown PC action ' + name };
  }
}

/** Files that run something when opened (programs, scripts, installers, shortcuts): Atlas asks before opening these. */
const RUNS = new Set(['exe', 'com', 'bat', 'cmd', 'ps1', 'psm1', 'psd1', 'vbs', 'vbe', 'vb', 'js', 'jse', 'wsf', 'wsh', 'ws', 'msi', 'msp', 'msix', 'msixbundle', 'appx',
  'appxbundle', 'application', 'scr', 'hta', 'lnk', 'reg', 'cpl', 'msc', 'jar', 'pif', 'appref-ms', 'url', 'scf', 'inf', 'chm', 'settingcontent-ms',
  'diagcab', 'gadget', 'xbap', 'iso', 'img', 'vhd', 'vhdx', 'py', 'pyw', 'pyz', 'pyzw', 'sh']);   // Python and Git Bash run their scripts on open
// Windows ignores trailing dots and spaces ("setup.exe." runs setup.exe) and a "::$DATA" stream suffix, so look past them
function runsSomething(p) {
  const s = String(p || '').trim().replace(/["']/g, '').replace(/::\$data$/i, '').replace(/[. ]+$/, '');
  return RUNS.has(path.extname(s).slice(1).toLowerCase());
}

module.exports = { run, loadAttachment, docxText, sendKeysText, sendKeysCombo, expand, q, runsSomething };

// What Atlas may do inside one of the user's projects without asking (desktop/projects.js uses this).
// Building inside the project's own folder is the point: writing its files and running its build, test and
// package-manager commands go ahead. Everything that reaches outside it asks first: other folders, global installs,
// publishing or pushing, system changes, deleting the project, and any command this file can't read with
// confidence (chains, redirects, variables, unknown programs). Pure: no Electron, no file system (testable anywhere).
'use strict';

/** Characters that can chain, redirect, substitute or hide a second command in cmd.exe, PowerShell or sh. */
const CHAINS = /[\r\n`$;|&<>^%!(){}]/;

/** Splits a command line into words the way a shell would for plain words and simple quotes (no expansion). */
function words(cmd) {
  const out = []; let cur = '', q = null, any = false;
  for (const ch of String(cmd || '')) {
    if (q) { if (ch === q) q = null; else cur += ch; continue; }
    if (ch === '"' || ch === "'") { q = ch; any = true; continue; }
    if (/\s/.test(ch)) { if (cur || any) out.push(cur); cur = ''; any = false; continue; }
    cur += ch;
  }
  if (q) return null;                 // an unclosed quote: can't be read with confidence
  if (cur || any) out.push(cur);
  return out;
}

/** A word that names a place outside the project: an absolute path, a drive, a UNC share, home (~), or any ".." step. */
function escapes(w) {
  if (/^\/[a-z?]{1,2}(:\S*)?$/i.test(String(w))) return false;   // a Windows switch like /s, /q, /b (not a path)
  const s = String(w).replace(/^--?[\w-]+=/, '');   // --out=../x → ../x
  if (/^[a-z]:/i.test(s) || s.startsWith('\\\\') || s.startsWith('/') || s.startsWith('\\') || s.startsWith('~')) return true;
  return s.split(/[\\/]+/).some((p) => p === '..');
}

/** The program a word names, without folders or .exe/.cmd/.bat (".venv/Scripts/python.exe" → "python"). */
const progOf = (w) => String(w || '').split(/[\\/]/).pop().toLowerCase().replace(/\.(exe|cmd|bat|ps1|sh)$/, '');
const viaVenv = (w) => /^(\.venv|venv|env)[\\/]+(scripts|bin)[\\/]+/i.test(String(w || ''));

const GLOBAL_FLAGS = new Set(['-g', '--global', '--location=global', '--user', '--system', '--break-system-packages', '--prefix', '--root']);
const SIMPLE = new Set(['node', 'tsc', 'eslint', 'prettier', 'jest', 'vitest', 'mocha', 'pytest', 'ruff', 'black', 'mypy', 'flake8', 'javac', 'java', 'deno', 'echo',
  'dir', 'ls', 'type', 'cat', 'mkdir', 'md', 'tree', 'where', 'which', 'gradle', 'gradlew', 'mvnw', 'make', 'cmake', 'ninja', 'rustc', 'gcc', 'g++', 'clang', 'vite', 'next', 'tsx', 'ts-node']);
const DELETE = new Set(['rm', 'del', 'erase', 'rmdir', 'rd', 'remove-item']);

/**
 * Should running [command] in the project folder ask first?
 * Returns { ask: false } or { ask: true, why, category } (category is one of the approval kinds in botx.js).
 * [hasVenv]: the project has its own Python environment (.venv / venv), so pip there stays inside the project.
 */
function checkCommand(command, { hasVenv = false } = {}) {
  const raw = String(command || '').trim();
  const ask = (why, category = 'command') => ({ ask: true, why, category });
  if (!raw) return ask('an empty command');
  if (raw.length > 600) return ask('a very long command');
  if (CHAINS.test(raw)) return ask('it chains, redirects or substitutes something');
  const w = words(raw);
  if (!w || !w.length) return ask("it couldn't be read clearly");
  if (w.some(escapes)) return ask('it points outside the project folder');
  const prog = progOf(w[0]), sub = (w[1] || '').toLowerCase(), rest = w.slice(1).map((x) => x.toLowerCase());
  const hasGlobal = rest.some((x) => GLOBAL_FLAGS.has(x) || x.startsWith('--prefix=') || x.startsWith('--root='));
  if (['sudo', 'runas', 'su', 'doas'].includes(prog)) return ask('it asks for administrator rights', 'account');
  if (['winget', 'choco', 'scoop', 'apt', 'apt-get', 'brew', 'msiexec', 'reg', 'regedit', 'sc', 'setx', 'net', 'netsh', 'bcdedit', 'icacls', 'takeown', 'format', 'diskpart', 'shutdown', 'powershell', 'pwsh', 'cmd', 'bash', 'sh', 'wsl', 'start', 'curl', 'wget', 'invoke-webrequest', 'iwr', 'ssh', 'scp'].includes(prog))
    return ask('it reaches beyond this project (system, other shells or the network)');
  if (DELETE.has(prog)) {
    const targets = w.slice(1).filter((x) => !x.startsWith('-') && !x.startsWith('/'));
    if (!targets.length || targets.some((t) => ['.', './', '.\\', '*', '*.*', '/'].includes(t) || /^[.\\/*]+$/.test(t))) return ask('it would delete the whole project', 'delete');
    return { ask: false };   // deleting named files inside the project is editing it
  }
  switch (prog) {
    case 'npm': case 'pnpm': case 'yarn': case 'bun': {
      if (hasGlobal || sub === 'global') return ask('a global install changes the whole PC');
      if (['publish', 'unpublish', 'deprecate', 'owner', 'access', 'adduser', 'login', 'logout', 'token', 'team', 'org', 'dist-tag', 'star', 'link', 'config', 'set'].includes(sub)) return ask(sub === 'publish' ? 'it publishes the package' : 'it changes your account or global settings', sub === 'publish' ? 'publish' : 'account');
      return { ask: false };
    }
    case 'npx': case 'pnpx': case 'bunx': {
      if (hasGlobal) return ask('a global install changes the whole PC');
      const tool = progOf(w.find((x, i) => i > 0 && !x.startsWith('-')) || '');
      if (/^(vercel|netlify|firebase|wrangler|surge|gh-pages|np|release-it|semantic-release|eas)$/.test(tool)) return ask('it deploys or publishes', 'publish');
      return { ask: false };
    }
    case 'python': case 'python3': case 'py': {
      const m = rest.indexOf('-m'), mod = m >= 0 ? rest[m + 1] : null;
      if (mod === 'pip') {
        if (!['install', 'uninstall'].includes(rest[m + 2])) return { ask: false };   // pip list / show / freeze
        if (hasGlobal) return ask('it installs for the whole PC');
        return viaVenv(w[0]) ? { ask: false } : ask(hasVenv ? "it installs into the PC's Python, not the project's own environment (use .venv\\Scripts\\python -m pip)" : 'it installs into the PC-wide Python (make a project environment first: python -m venv .venv)');
      }
      if (mod === 'twine' || mod === 'webbrowser' || mod === 'http.server') return ask(mod === 'twine' ? 'it publishes the package' : 'it opens or serves on the network', mod === 'twine' ? 'publish' : 'command');
      return { ask: false };
    }
    case 'pip': case 'pip3': {
      if (!['install', 'uninstall'].includes(sub)) return { ask: false };
      if (hasGlobal) return ask('it installs for the whole PC');
      return viaVenv(w[0]) ? { ask: false } : ask("it installs into the PC-wide Python, not the project's own environment");
    }
    case 'git': {
      const gsub = (rest.find((x) => !x.startsWith('-')) || '').toLowerCase();
      if (rest.includes('--global') || rest.includes('--system')) return ask('it changes your global git settings', 'account');
      if (['push', 'send-email', 'request-pull'].includes(gsub)) return ask('it sends your code out (push)', 'publish');
      if (['init', 'add', 'commit', 'status', 'log', 'diff', 'show', 'branch', 'checkout', 'switch', 'restore', 'stash', 'tag', 'rm', 'mv', 'clone', 'pull', 'fetch', 'merge', 'rebase', 'reset', 'remote', 'config', 'rev-parse', 'ls-files', 'describe', 'blame', 'shortlog', 'grep'].includes(gsub)) return { ask: false };
      return ask("it's a git command Atlas doesn't know is safe");
    }
    case 'cargo': {
      if (['publish', 'install', 'login', 'owner', 'yank'].includes(sub)) return ask(sub === 'publish' ? 'it publishes the crate' : 'it installs for the whole PC or changes your account', sub === 'publish' ? 'publish' : 'command');
      return { ask: false };
    }
    case 'dotnet': {
      if (sub === 'tool' && (rest.includes('install') || rest.includes('update')) && hasGlobal) return ask('a global tool install changes the whole PC');
      if (sub === 'nuget' && rest.includes('push')) return ask('it publishes the package', 'publish');
      if (sub === 'workload' || sub === 'dev-certs') return ask('it changes the PC-wide .NET setup');
      return { ask: false };
    }
    case 'go': {
      if (sub === 'install') return ask('it installs for the whole PC');
      return { ask: false };
    }
    case 'flutter': case 'dart': {
      if (rest.includes('publish')) return ask('it publishes the package', 'publish');
      if (sub === 'upgrade' || sub === 'channel' || sub === 'config' || (sub === 'pub' && rest.includes('global'))) return ask('it changes the PC-wide Flutter setup');
      return { ask: false };
    }
    case 'mvn': {
      if (rest.includes('deploy') || rest.includes('release:perform')) return ask('it deploys or publishes', 'publish');
      return { ask: false };
    }
    case 'code': case 'explorer': return { ask: false };   // opening the project in an editor / the folder
    default:
      if (SIMPLE.has(prog)) return { ask: false };
      if (viaVenv(w[0])) return { ask: false };              // the project's own environment's tools
      if (/^\.[\\/]/.test(w[0]) || /^(node_modules[\\/]\.bin|bin|scripts?|gradlew)\b/i.test(w[0])) return { ask: false };   // the project's own scripts
      return ask(`Atlas doesn't know "${prog}" is safe`);
  }
}

/**
 * A path inside the project, given as the bot wrote it ("src/app.js"): the parts, or null when it would leave the
 * project (.., absolute, a drive, a share, home) or names something Atlas keeps out of (.git internals, the manifest).
 */
function relPath(p) {
  const s = String(p == null ? '' : p).trim().replace(/\\/g, '/');
  if (!s || s.length > 400 || escapes(s) || /[\x00-\x1f<>:"|?*]/.test(s)) return null;
  const parts = s.split('/').filter((x) => x && x !== '.');
  if (!parts.length || parts.some((x) => /^[\s.]+$/.test(x) || /[.\s]$/.test(x))) return null;
  if (parts[0].toLowerCase() === '.git' && parts.length > 1) return null;
  return parts;
}

/** A project's folder name from what the user or bot called it. */
function projectName(s) {
  const t = String(s || '').replace(/[<>:"/\\|?*\x00-\x1f]/g, ' ').replace(/\s+/g, ' ').trim().replace(/^[.\s]+|[.\s]+$/g, '').slice(0, 60).trim();
  if (/^(con|prn|aux|nul|com\d|lpt\d)$/i.test(t)) return t + ' project';
  return t;
}

/** How to check a project, from the files it has (the manifest's own check command wins). [has]: a name → exists test. */
function checkPlan(has, manifest = {}) {
  if (manifest && manifest.check) return manifest.check;
  if (has('package.json')) return 'npm test';
  if (has('Cargo.toml')) return 'cargo test';
  if (has('go.mod')) return 'go test ./...';
  if (has('gradlew') || has('gradlew.bat')) return 'gradlew test';
  if (has('pyproject.toml') || has('requirements.txt') || has('setup.py') || has('tests') || has('test')) return null;   // python: decided by the caller (venv, pytest)
  return null;
}

/** The last [max] characters of output, with a note when the start was dropped. */
function tail(text, max = 12000) {
  const s = String(text || '');
  return s.length > max ? `[${s.length - max} earlier characters not shown]\n` + s.slice(-max) : s;
}

module.exports = { checkCommand, relPath, projectName, checkPlan, tail, words, escapes };

// The user's software projects on this PC: Documents/Atlas Projects/<name>. Atlas builds them here (from the chat,
// from a bot, or for the phone through the Device Link): writes the files, runs the build and the tests, reads the
// errors, fixes them, and hands over a zip in the Library.
// Runs in the main process. Every path a bot gives stays inside its project (projectrules.relPath); every command runs
// in the project folder and is checked first (projectrules.checkCommand): building, testing and package installs
// inside the project go ahead, anything reaching outside it comes back as "needs the user's OK" unless already approved.
'use strict';
const path = require('path');
const fs = require('fs');
const os = require('os');
const { spawn, execFile } = require('child_process');
const rules = require('./projectrules');
const el = (() => { try { const e = require('electron'); return typeof e === 'object' ? e : {}; } catch { return {}; } })();

const MANIFEST = '.atlas-project.json';
const SKIP = new Set(['node_modules', '.git', '.venv', 'venv', 'env', '__pycache__', '.pytest_cache', '.mypy_cache', 'target', 'bin', 'obj', '.gradle', '.dart_tool', '.next', '.idea', '.vs']);
const MAX_READ = 24000, MAX_WRITE = 2 * 1024 * 1024, MAX_TREE = 400, MAX_ZIP = 200 * 1024 * 1024;
const DEFAULT_TIMEOUT = 180, MAX_TIMEOUT = 1800;
const isWin = process.platform === 'win32';

let baseOverride = null;
/** Documents/Atlas Projects (tests point it elsewhere). */
const base = () => baseOverride || path.join(el.app ? el.app.getPath('documents') : os.homedir(), 'Atlas Projects');
function configure({ dir } = {}) { if (dir) baseOverride = dir; }

// ---------------------------------------------------------------- projects and their manifests

function dirOf(name) {
  const n = rules.projectName(name);
  if (!n) return null;
  return path.join(base(), n);
}
function readManifest(dir) { try { return JSON.parse(fs.readFileSync(path.join(dir, MANIFEST), 'utf8')); } catch { return null; } }
function writeManifest(dir, m) {
  const f = path.join(dir, MANIFEST), tmp = f + '.tmp';
  m.history = (m.history || []).slice(-80);
  fs.writeFileSync(tmp, JSON.stringify(m, null, 2), 'utf8'); fs.renameSync(tmp, f);
}
function note(dir, what, extra = {}) {
  const m = readManifest(dir); if (!m) return;
  Object.assign(m, extra, { updatedAt: Date.now() });
  m.history = [...(m.history || []), { at: Date.now(), what: String(what).slice(0, 300) }];
  writeManifest(dir, m);
}
/** The project folder for [name], which must exist (made with project_new). */
function existing(name) {
  const dir = dirOf(name);
  if (!dir || !fs.existsSync(dir) || !fs.statSync(dir).isDirectory()) return null;
  return dir;
}
/** A path inside the project, or null. Atlas's own manifest is kept out of the bot's reach. */
function inside(dir, p) {
  const parts = rules.relPath(p);
  if (!parts || parts[0] === MANIFEST) return null;
  const f = path.join(dir, ...parts);
  const r = path.resolve(f), d = path.resolve(dir) + path.sep;
  return r.startsWith(d) ? r : null;
}
const hasVenv = (dir) => ['.venv', 'venv'].some((v) => fs.existsSync(path.join(dir, v)));

function list() {
  let names = [];
  try { names = fs.readdirSync(base(), { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name); } catch { return []; }
  return names.map((n) => { const m = readManifest(path.join(base(), n)) || {}; return { name: n, goal: m.goal || '', status: m.status || '', stack: m.stack || '', updatedAt: m.updatedAt || 0, dir: path.join(base(), n) }; })
    .sort((a, b) => b.updatedAt - a.updatedAt);
}

function tree(dir, sub = '') {
  const out = []; let more = 0;
  const walk = (d, rel, depth) => {
    let ents = [];
    try { ents = fs.readdirSync(d, { withFileTypes: true }); } catch { return; }
    ents.sort((a, b) => (b.isDirectory() - a.isDirectory()) || a.name.localeCompare(b.name));
    for (const e of ents) {
      if (e.name === MANIFEST || e.name.endsWith('.tmp')) continue;
      const r = rel ? rel + '/' + e.name : e.name;
      if (out.length >= MAX_TREE) { more++; continue; }
      if (e.isDirectory()) {
        if (SKIP.has(e.name)) { out.push(r + '/ (not listed)'); continue; }
        out.push(r + '/');
        if (depth < 8) walk(path.join(d, e.name), r, depth + 1);
      } else {
        let size = 0; try { size = fs.statSync(path.join(d, e.name)).size; } catch {}
        out.push(`${r}  (${size < 1024 ? size + ' B' : Math.round(size / 1024) + ' KB'})`);
      }
    }
  };
  walk(sub ? path.join(dir, sub) : dir, sub, 0);
  return out.join('\n') + (more ? `\n…and ${more} more` : '') || '(empty)';
}

// ---------------------------------------------------------------- what's installed on this PC (to pick a stack)

let toolCache = null;
function version(cmd) {
  return new Promise((resolve) => {
    const opts = { timeout: 6000, windowsHide: true, shell: isWin, maxBuffer: 256 * 1024 };
    execFile(cmd, ['--version'], opts, (err, out, errOut) => {
      if (err) return resolve(null);
      const line = String(out || errOut || '').split(/\r?\n/).find((l) => /\d/.test(l)) || '';
      resolve(line.trim().slice(0, 60) || 'installed');
    });
  });
}
async function toolchains() {
  if (toolCache && Date.now() - toolCache.at < 10 * 60000) return toolCache.list;
  const names = isWin ? ['node', 'npm', 'python', 'py', 'git', 'code', 'dotnet', 'java', 'cargo', 'go', 'flutter'] : ['node', 'npm', 'python3', 'git', 'code', 'dotnet', 'java', 'cargo', 'go', 'flutter'];
  const vs = await Promise.all(names.map(version));
  const list = names.map((n, i) => ({ name: n, version: vs[i] })).filter((x) => x.version);
  toolCache = { at: Date.now(), list };
  return list;
}
const pythonCmd = async () => { const t = await toolchains(); return t.some((x) => x.name === 'python') ? 'python' : t.some((x) => x.name === 'py') ? 'py' : 'python3'; };

// ---------------------------------------------------------------- running commands in a project

const running = new Map();   // dir → the command running there now (one at a time per project)
let active = 0;              // across all projects; builds wait for a slot so the PC stays usable
const MAX_ACTIVE = 2;
const apps = new Map();      // dir → a long-running app started with project_open how=app

const stripAnsi = (s) => String(s).replace(/\x1b\[[0-9;?]*[ -/]*[@-~]/g, '').replace(/\r(?!\n)/g, '\n');
function killTree(child) {
  if (!child || child.exitCode != null) return;
  try {
    if (isWin) execFile('taskkill', ['/PID', String(child.pid), '/T', '/F'], { windowsHide: true }, () => {});
    else process.kill(-child.pid, 'SIGKILL');
  } catch { try { child.kill('SIGKILL'); } catch {} }
}
function shellSpawn(command, cwd, detached) {
  const env = { ...process.env, CI: '1', FORCE_COLOR: '0', NO_COLOR: '1', PYTHONUNBUFFERED: '1', PYTHONDONTWRITEBYTECODE: '1' /* fast fixes keep size and mtime second: no stale .pyc */, PYTHONIOENCODING: 'utf-8', NPM_CONFIG_FUND: 'false', NPM_CONFIG_AUDIT: 'false', NPM_CONFIG_UPDATE_NOTIFIER: 'false' };
  const child = isWin
    ? spawn(process.env.ComSpec || 'cmd.exe', ['/d', '/s', '/c', `"${command}"`], { cwd, env, windowsHide: true, windowsVerbatimArguments: true, stdio: ['ignore', 'pipe', 'pipe'], detached: !!detached })
    : spawn('/bin/sh', ['-c', command], { cwd, env, stdio: ['ignore', 'pipe', 'pipe'], detached: true });
  // builds run a notch below normal so the PC stays responsive while Atlas works
  try { os.setPriority(child.pid, os.constants.priority.PRIORITY_BELOW_NORMAL); } catch {}
  return child;
}
async function waitTurn(dir) {
  while (running.has(dir) || active >= MAX_ACTIVE) await new Promise((r) => setTimeout(r, 300));
}
/** Runs [command] in [dir] and resolves with { code, out, timedOut }. Output is kept to the last part. */
async function exec(dir, command, timeoutS) {
  await waitTurn(dir);
  running.set(dir, command); active++;
  try {
    return await new Promise((resolve) => {
      let out = '', timedOut = false;
      const child = shellSpawn(command, dir, false);
      const add = (b) => { out += b.toString('utf8'); if (out.length > 400000) out = out.slice(-200000); };
      child.stdout.on('data', add); child.stderr.on('data', add);
      const t = setTimeout(() => { timedOut = true; killTree(child); }, Math.min(MAX_TIMEOUT, Math.max(5, timeoutS || DEFAULT_TIMEOUT)) * 1000);
      child.on('error', (e) => { clearTimeout(t); resolve({ code: -1, out: String(e.message || e), timedOut }); });
      child.on('close', (code) => { clearTimeout(t); resolve({ code: code == null ? -1 : code, out: stripAnsi(out), timedOut }); });
    });
  } finally { running.delete(dir); active--; }
}
const result = (command, r) => `$ ${command}\n${rules.tail(r.out).trim() || '(no output)'}\n\n` + (r.timedOut ? 'Stopped: it ran past its time limit (raise timeout_s if it needs longer, or run it in the background with project_open how=app).' : `Finished with exit code ${r.code}${r.code === 0 ? ' (success)' : ' (failed)'}.`);

/** The command that checks this project (its tests, or a build), or null when Atlas can't tell. */
async function checkCommandFor(dir, m) {
  const has = (n) => fs.existsSync(path.join(dir, n));
  let cmd = rules.checkPlan(has, m || {});
  if (cmd === 'npm test') {
    let pkg = {}; try { pkg = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8')); } catch {}
    const t = pkg.scripts && pkg.scripts.test;
    if (!t || /no test specified/.test(t)) cmd = pkg.scripts && pkg.scripts.build ? 'npm run build' : null;
  }
  if (cmd) return cmd;
  const isPy = ['pyproject.toml', 'requirements.txt', 'setup.py', 'main.py', 'app.py'].some(has) || fs.readdirSync(dir).some((f) => /\.py$/.test(f));
  if (isPy) {
    const venv = ['.venv', 'venv'].find(has);
    const py = venv ? path.join(venv, isWin ? 'Scripts' : 'bin', 'python') : await pythonCmd();
    const pytest = venv && [path.join(venv, 'Lib', 'site-packages', 'pytest'), ...(() => { try { return fs.readdirSync(path.join(dir, venv, 'lib')).map((p) => path.join(venv, 'lib', p, 'site-packages', 'pytest')); } catch { return []; } })()].some(has);
    return pytest ? `${py} -m pytest -q` : `${py} -m unittest discover -v`;
  }
  if (fs.readdirSync(dir).some((f) => /\.(csproj|sln)$/.test(f))) return 'dotnet test';
  return null;
}

// ---------------------------------------------------------------- the tools

const NAMES = ['project_list', 'project_new', 'project_files', 'project_read', 'project_write', 'project_patch', 'project_run', 'project_check', 'project_open', 'project_zip', 'project_delete'];

/**
 * Would [name] with [args] need the user's OK? A sentence saying what would happen, or null.
 * The same check run() makes, asked ahead (for Atlas Bot's approval step).
 */
async function check(name, args = {}) {
  const dir = existing(args.project);
  if (name === 'project_delete') return `Delete the whole project "${rules.projectName(args.project) || args.project}" from Documents\\Atlas Projects`;
  if (!dir) return null;   // the tool itself will say the project doesn't exist
  if (name === 'project_run' || (name === 'project_check' && args.command) || (name === 'project_open' && args.how === 'app')) {
    const command = String(args.command || (name === 'project_open' ? (readManifest(dir) || {}).run || '' : ''));
    if (!command && name !== 'project_run') return null;
    const r = rules.checkCommand(command, { hasVenv: hasVenv(dir) });
    return r.ask ? `Run this in the project "${path.basename(dir)}" (${r.why}): ${command.slice(0, 160)}` : null;
  }
  return null;
}

/** Runs one project tool. { out, step?, needs?, made? }. Without [approved], something risky comes back as { needs } instead of running. */
async function run(name, args = {}, { approved = false, library = null } = {}) {
  if (!NAMES.includes(name)) return { out: 'Error: there is no such project tool.' };
  if (name === 'project_list') {
    const l = list();
    const tc = await toolchains();
    return { out: (l.length ? 'Projects (newest first):\n' + l.slice(0, 40).map((p) => `- ${p.name}${p.status ? ` [${p.status}]` : ''}${p.goal ? ': ' + p.goal.slice(0, 120) : ''}`).join('\n') : 'No projects yet.')
      + `\n\nInstalled on this PC: ${tc.map((t) => `${t.name} (${t.version})`).join(', ') || 'none of the usual developer tools were found'}.\nProjects live in ${base()}.` };
  }
  if (name === 'project_new') {
    const n = rules.projectName(args.name);
    if (!n) return { out: 'Error: give the project a name.' };
    const dir = path.join(base(), n);
    const existed = fs.existsSync(dir);
    fs.mkdirSync(dir, { recursive: true });
    if (!readManifest(dir)) writeManifest(dir, { name: n, goal: String(args.goal || '').slice(0, 4000), stack: String(args.stack || '').slice(0, 200), run: '', check: '', status: 'started', createdAt: Date.now(), updatedAt: Date.now(), history: [{ at: Date.now(), what: 'Started the project' }] });
    else if (args.goal || args.stack) note(dir, 'Updated the goal', { ...(args.goal ? { goal: String(args.goal).slice(0, 4000) } : {}), ...(args.stack ? { stack: String(args.stack).slice(0, 200) } : {}) });
    const tc = await toolchains();
    return { out: `${existed ? 'Opened the existing' : 'Made the'} project "${n}" at ${dir}.\nInstalled on this PC: ${tc.map((t) => `${t.name} (${t.version})`).join(', ') || 'none of the usual developer tools'}.\nPick a stack that is installed. Write files with project_write, run with project_run, check with project_check.`, step: (existed ? 'Opened the project ' : 'Started the project ') + n };
  }
  const dir = existing(args.project);
  if (!dir) return { out: `Error: there's no project called "${args.project}". Start it with project_new (project_list shows the ones that exist).` };
  const pname = path.basename(dir);
  switch (name) {
    case 'project_files': {
      const sub = args.path ? rules.relPath(args.path) : null;
      if (args.path && !sub) return { out: 'Error: that path is outside the project.' };
      return { out: `Files in ${pname}${sub ? '/' + sub.join('/') : ''}:\n` + tree(dir, sub ? sub.join('/') : '') };
    }
    case 'project_read': {
      const f = inside(dir, args.path); if (!f) return { out: 'Error: that path is outside the project.' };
      if (!fs.existsSync(f) || !fs.statSync(f).isFile()) return { out: `Error: ${args.path} doesn't exist (project_files lists what's there).` };
      const buf = fs.readFileSync(f);
      if (buf.includes(0)) return { out: `${args.path} is a binary file (${buf.length} bytes); it can't be read as text.` };
      const text = buf.toString('utf8'), from = Math.max(0, Number(args.from) || 0);
      const part = text.slice(from, from + MAX_READ);
      return { out: part + (text.length > from + MAX_READ ? `\n\n[${text.length - from - MAX_READ} more characters: read again with from=${from + MAX_READ}]` : ''), step: 'Read ' + args.path };
    }
    case 'project_write': {
      const f = inside(dir, args.path); if (!f) return { out: 'Error: that path is outside the project.' };
      const text = String(args.text ?? '');
      if (Buffer.byteLength(text) > MAX_WRITE) return { out: 'Error: that is too long for one file (2 MB at most).' };
      fs.mkdirSync(path.dirname(f), { recursive: true });
      const existed = fs.existsSync(f);
      fs.writeFileSync(f, text, 'utf8');
      return { out: `${existed ? 'Replaced' : 'Wrote'} ${args.path} (${text.split('\n').length} lines).`, step: (existed ? 'Rewrote ' : 'Wrote ') + args.path };
    }
    case 'project_patch': {
      const f = inside(dir, args.path); if (!f) return { out: 'Error: that path is outside the project.' };
      if (!fs.existsSync(f)) return { out: `Error: ${args.path} doesn't exist; write it with project_write.` };
      const text = fs.readFileSync(f, 'utf8'), find = String(args.find ?? ''), repl = String(args.replace ?? '');
      if (!find) return { out: 'Error: give the exact text to find.' };
      const n = text.split(find).length - 1;
      if (!n) return { out: `Error: that exact text isn't in ${args.path}. Read the file again (project_read) and copy the text exactly, including spaces.` };
      if (n > 1 && !args.all) return { out: `Error: that text appears ${n} times in ${args.path}. Include more of the surrounding lines so it's unique, or set all=true to change every one.` };
      fs.writeFileSync(f, args.all ? text.split(find).join(repl) : text.replace(find, () => repl), 'utf8');
      return { out: `Changed ${n > 1 ? n + ' places' : 'one place'} in ${args.path}.`, step: 'Edited ' + args.path };
    }
    case 'project_run': {
      const command = String(args.command || '').trim();
      if (!command) return { out: 'Error: give the command to run.' };
      if (!approved) { const c = rules.checkCommand(command, { hasVenv: hasVenv(dir) }); if (c.ask) return { needs: `Run this in the project "${pname}" (${c.why}): ${command.slice(0, 160)}`, category: c.category, out: '' }; }
      const r = await exec(dir, command, Number(args.timeout_s) || DEFAULT_TIMEOUT);
      note(dir, `Ran ${command.slice(0, 120)} → ${r.timedOut ? 'timed out' : 'exit ' + r.code}`);
      return { out: result(command, r), step: `Ran ${command.slice(0, 60)}${r.code === 0 ? '' : r.timedOut ? ' (timed out)' : ' (failed)'}` };
    }
    case 'project_check': {
      const m = readManifest(dir) || {};
      let command = String(args.command || '').trim();
      if (command && !approved) { const c = rules.checkCommand(command, { hasVenv: hasVenv(dir) }); if (c.ask) return { needs: `Use this as the project's check (${c.why}): ${command.slice(0, 160)}`, category: c.category, out: '' }; }
      if (command) note(dir, 'Set the check command', { check: command });
      else command = await checkCommandFor(dir, m);
      if (!command) return { out: "Error: Atlas can't tell how to check this project yet. Give the command (e.g. project_check with command \"npm test\" or \"python -m pytest -q\"); it's remembered for next time." };
      // a Node project whose packages aren't installed yet: install them first
      let pre = '';
      if (/^npm (test|run )/.test(command) && fs.existsSync(path.join(dir, 'package.json')) && !fs.existsSync(path.join(dir, 'node_modules'))) {
        let pkg = {}; try { pkg = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8')); } catch {}
        if (Object.keys({ ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) }).length) {
          const ri = await exec(dir, 'npm install', 600);
          pre = result('npm install', ri) + '\n\n';
          if (ri.code !== 0) return { out: pre + 'The packages failed to install, so the check didn\'t run.', step: 'Checked: the install failed' };
        }
      }
      const r = await exec(dir, command, Number(args.timeout_s) || 600);
      const passed = r.code === 0 && !r.timedOut;
      note(dir, `Checked with ${command} → ${passed ? 'passed' : 'failed'}`, { status: passed ? 'checks pass' : 'checks fail', lastCheck: { at: Date.now(), command, passed } });
      return { out: pre + result(command, r) + (passed ? '\nThe check PASSED.' : '\nThe check FAILED: read the errors above, fix the code, and check again.'), step: passed ? `Checked: it passes (${command})` : `Checked: it fails (${command})` };
    }
    case 'project_open': {
      const how = String(args.how || 'folder');
      if (how === 'folder') { if (el.shell) el.shell.openPath(dir); return { out: `Opened the folder ${dir}.`, step: 'Opened the project folder' }; }
      if (how === 'editor') {
        const hasCode = (await toolchains()).some((t) => t.name === 'code');
        if (!hasCode) { if (el.shell) el.shell.openPath(dir); return { out: "VS Code isn't installed, so the folder was opened instead.", step: 'Opened the project folder' }; }
        const c = shellSpawn('code .', dir, true); c.unref(); c.stdout.resume(); c.stderr.resume();
        return { out: 'Opened the project in VS Code.', step: 'Opened the project in VS Code' };
      }
      if (how === 'stop') { const a = apps.get(dir); if (!a) return { out: 'Nothing of this project is running.' }; killTree(a.child); apps.delete(dir); return { out: `Stopped ${a.command}.`, step: 'Stopped the app' }; }
      if (how === 'app') {
        const m = readManifest(dir) || {};
        const command = String(args.command || m.run || '').trim();
        if (!command) return { out: "Error: say how to start it (command), e.g. \"npm start\" or \"python app.py\"; it's remembered for next time." };
        if (!approved) { const c = rules.checkCommand(command, { hasVenv: hasVenv(dir) }); if (c.ask) return { needs: `Start this from the project "${pname}" (${c.why}): ${command.slice(0, 160)}`, category: c.category, out: '' }; }
        const prev = apps.get(dir); if (prev) killTree(prev.child);
        const child = shellSpawn(command, dir, true);
        let out = ''; const add = (b) => { out = (out + b.toString('utf8')).slice(-20000); };
        child.stdout.on('data', add); child.stderr.on('data', add);
        apps.set(dir, { child, command, get out() { return out; } });
        child.on('close', () => { if (apps.get(dir) && apps.get(dir).child === child) apps.delete(dir); });
        if (args.command) note(dir, 'Set how to start it', { run: command });
        await new Promise((r) => setTimeout(r, 4000));
        const alive = child.exitCode == null;
        return { out: `${alive ? 'Started' : 'It started and already ended'}: ${command}\nFirst output:\n${rules.tail(stripAnsi(out), 3000).trim() || '(nothing yet)'}${alive ? '\nIt keeps running in the background (project_open how=stop ends it).' : `\nExit code ${child.exitCode}.`}`, step: alive ? 'Started the app: ' + command.slice(0, 60) : 'Ran the app: ' + command.slice(0, 60) };
      }
      return { out: 'Error: how is one of folder, editor, app or stop.' };
    }
    case 'project_zip': {
      const files = []; let total = 0, skipped = 0;
      const walk = (d, rel) => {
        for (const e of fs.readdirSync(d, { withFileTypes: true })) {
          const r = rel ? rel + '/' + e.name : e.name;
          if (e.isDirectory()) { if (SKIP.has(e.name) && e.name !== 'bin') { skipped++; continue; } walk(path.join(d, e.name), r); continue; }
          if (!e.isFile() || e.name.endsWith('.tmp') || (!rel && e.name === MANIFEST)) continue;
          const f = path.join(d, e.name), size = fs.statSync(f).size;
          if (total + size > MAX_ZIP) { skipped++; continue; }
          total += size; files.push({ name: path.basename(dir) + '/' + r, data: fs.readFileSync(f) });
        }
      };
      walk(dir, '');
      const zip = require('./sheets').zip(files);
      if (!library) return { out: "Error: the Library isn't available." };
      const made = library(pname, zip);
      note(dir, 'Zipped it to the Library');
      return { out: `Zipped ${files.length} files (${Math.round(zip.length / 1024)} KB) to ${made.name} in the Library${skipped ? ` (left out ${skipped} things like node_modules, .git and the Python environment, which can be rebuilt)` : ''}.`, step: 'Zipped the project to the Library', made: made.name };
    }
    case 'project_delete': {
