  if (go.dataset.k === k) return;
  go.dataset.k = k; go.innerHTML = k === 'stop' ? ICON.stop : k === 'send' ? ICON.up : ICON.mic; go.title = k === 'stop' ? 'Stop' : k === 'send' ? 'Send' : 'Speak';
