  const off = progressTo(id, (d, t) => { if (!adding || adding.id !== id) return; adding.line = `Adding ${name} · ${t ? Math.floor(d * 100 / t) : 0}% of ${AR.sizeText(t)} · click to stop`; const el = $('#tray .adding'); if (el) el.textContent = adding.line; });
