  cards.forEach((c, i) => {
    let el = box.querySelector(`[data-job="${CSS.escape(c.id)}"]`);
    const sig = JSON.stringify([c.label, c.title, c.step, c.lit, c.counts, c.time, !!c.approval, c.question]);
    if (el && el.dataset.sig === sig) return;
