  if (ms == null) return { ok: false, error: `Couldn't read the time “${raw}”. Use 'YYYY-MM-DD HH:MM', or words like “tomorrow at 6pm” or “in 90 minutes”.` };
  if (!allowPast && ms < now - MIN) return { ok: false, error: `${fmtLong(ms, tz)} has already passed (it's ${fmtLong(now, tz)} now). Use the next time it comes round, or ask the user.` };
  if (ms - now > 5 * 366 * DAY) return { ok: false, error: `${fmtLong(ms, tz)} is more than five years away. Check the year.` };
  return { ok: true, ms, local: fmtLocal(ms, tz), long: fmtLong(ms, tz), relative: relativeDay(ms, now, tz) };
}

/** "today", "tomorrow", "in 3 days" — how far off the day is, for read-backs. */
export function relativeDay(ms, now, tz) {
  const a = partsIn(ms, tz), b = partsIn(now, tz);
  const diff = Math.round((Date.UTC(a.y, a.mo - 1, a.d) - Date.UTC(b.y, b.mo - 1, b.d)) / DAY);
  return diff === 0 ? 'today' : diff === 1 ? 'tomorrow' : diff === -1 ? 'yesterday' : diff > 1 ? `in ${diff} days` : `${-diff} days ago`;
}

export const REPEATS = ['none', 'daily', 'weekdays', 'weekly'];
/** "every day" / "Daily" / "" → "daily"; null when it isn't one Atlas can do. */
export function normRepeat(v) {
  const t = String(v ?? '').trim().toLowerCase().replace(/[^a-z ]/g, '');
  if (!t || t === 'none' || t === 'no' || t === 'once' || t === 'never') return 'none';
  if (['daily', 'every day', 'everyday', 'each day'].includes(t)) return 'daily';
  if (['weekdays', 'every weekday', 'weekday', 'mondays to fridays', 'monday to friday'].includes(t)) return 'weekdays';
  if (['weekly', 'every week', 'each week'].includes(t)) return 'weekly';
  return null;
}

/** A whole number in [min, max], or null. Accepts "30", 30, "30 minutes", "1.5 hours" (for duration fields). */
export function normMinutes(v, min, max) {
  if (v == null || v === '') return null;
  const t = String(v).trim().toLowerCase(); const m = t.match(/^(\d+(?:\.\d+)?) ?(h|hours?|hrs?|m|mins?|minutes?)?$/);
  if (!m) return NaN;
  const n = Math.round(+m[1] * (m[2] && m[2][0] === 'h' ? 60 : 1));
  return n >= min && n <= max ? n : NaN;
}

/** This device's time zone (the user's), e.g. "Africa/Lagos". */
export const localZone = () => { try { return Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'; } catch { return 'UTC'; } };

// Spreadsheets for Atlas Bot, with nothing to install: reads CSV text, and writes a real Excel file (.xlsx is a zip of
// small XML files). Cells that start with "=" become formulas; numbers become numbers; the first row is the bold header.
'use strict';
const zlib = require('zlib');

/** CSV text → rows of cells (quotes, commas and line breaks inside quotes handled). */
function parseCsv(text) {
  const s = String(text || '').replace(/^﻿/, '');
  const rows = []; let row = [], cell = '', quoted = false, i = 0, any = false;
  while (i < s.length) {
    const c = s[i];
    if (quoted) {
      if (c === '"') { if (s[i + 1] === '"') { cell += '"'; i += 2; continue; } quoted = false; i++; continue; }
      cell += c; i++; continue;
    }
    if (c === '"' && cell === '') { quoted = true; any = true; i++; continue; }
    if (c === ',') { row.push(cell); cell = ''; any = true; i++; continue; }
    if (c === '\r') { i++; continue; }
    if (c === '\n') { row.push(cell); rows.push(row); row = []; cell = ''; any = false; i++; continue; }
    cell += c; any = true; i++;
  }
  if (any || cell !== '' || row.length) { row.push(cell); rows.push(row); }
  return rows.filter((r) => r.some((x) => String(x).trim() !== ''));
}

/** Rows → CSV text (Excel-friendly: CRLF, quotes where needed). */
function toCsv(rows) {
  return rows.map((r) => r.map((v) => { const t = String(v ?? ''); return /[",\r\n]/.test(t) || /^\s|\s$/.test(t) ? '"' + t.replace(/"/g, '""') + '"' : t; }).join(',')).join('\r\n') + '\r\n';
}

// ---- a tiny zip writer

const CRC = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
function crc32(buf) { let c = 0xFFFFFFFF; for (let i = 0; i < buf.length; i++) c = CRC[(c ^ buf[i]) & 0xFF] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; }

/** files: [{name, data: Buffer|string}] → one zip Buffer. */
function zip(files) {
  const parts = [], central = []; let offset = 0;
  for (const f of files) {
    const name = Buffer.from(f.name, 'utf8');
    const raw = Buffer.isBuffer(f.data) ? f.data : Buffer.from(String(f.data), 'utf8');
    const data = zlib.deflateRawSync(raw);
    const crc = crc32(raw);
    const head = Buffer.alloc(30);
    head.writeUInt32LE(0x04034b50, 0); head.writeUInt16LE(20, 4); head.writeUInt16LE(0x0800, 6); head.writeUInt16LE(8, 8);
    head.writeUInt16LE(0, 10); head.writeUInt16LE(0x21, 12);          // time 00:00, date 1980-01-01
    head.writeUInt32LE(crc, 14); head.writeUInt32LE(data.length, 18); head.writeUInt32LE(raw.length, 22);
    head.writeUInt16LE(name.length, 26); head.writeUInt16LE(0, 28);
    parts.push(head, name, data);
    const c = Buffer.alloc(46);
    c.writeUInt32LE(0x02014b50, 0); c.writeUInt16LE(20, 4); c.writeUInt16LE(20, 6); c.writeUInt16LE(0x0800, 8); c.writeUInt16LE(8, 10);
    c.writeUInt16LE(0, 12); c.writeUInt16LE(0x21, 14);
    c.writeUInt32LE(crc, 16); c.writeUInt32LE(data.length, 20); c.writeUInt32LE(raw.length, 24);
    c.writeUInt16LE(name.length, 28); c.writeUInt32LE(offset, 42);
    central.push(c, name);
    offset += head.length + name.length + data.length;
  }
  const cd = Buffer.concat(central);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(files.length, 8); end.writeUInt16LE(files.length, 10);
  end.writeUInt32LE(cd.length, 12); end.writeUInt32LE(offset, 16);
  return Buffer.concat([...parts, cd, end]);
}

// ---- the Excel file

const x = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
function col(n) { let s = ''; n++; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; }
const isNumber = (t) => /^-?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$/i.test(t) && t.length < 16 && !/^-?0\d/.test(t);
const sheetName = (s, i) => (String(s || '').replace(/[\\/?*[\]:]/g, ' ').trim().slice(0, 31) || `Sheet${i + 1}`);

function sheetXml(rows) {
  const widths = [];
  const body = rows.map((r, ri) => {
    const cells = r.map((v, ci) => {
      const t = String(v ?? ''); const ref = col(ci) + (ri + 1);
      widths[ci] = Math.min(60, Math.max(widths[ci] || 8, t.length + 2));
      const style = ri === 0 ? ' s="1"' : '';
      if (t === '') return '';
      if (t.startsWith('=') && t.length > 1) return `<c r="${ref}"${style}><f>${x(t.slice(1))}</f></c>`;
      if (isNumber(t.trim())) return `<c r="${ref}"${style}><v>${t.trim()}</v></c>`;
      return `<c r="${ref}"${style} t="inlineStr"><is><t xml:space="preserve">${x(t)}</t></is></c>`;
    }).join('');
    return `<row r="${ri + 1}">${cells}</row>`;
  }).join('');
  const cols = widths.length ? '<cols>' + widths.map((w, i) => `<col min="${i + 1}" max="${i + 1}" width="${w || 8}" customWidth="1"/>`).join('') + '</cols>' : '';
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>${cols}<sheetData>${body}</sheetData></worksheet>`;
}

/** sheets: [{name, rows}] → the .xlsx file as a Buffer. */
function xlsx(sheets) {
  const list = sheets.map((s, i) => ({ name: sheetName(s.name, i), rows: s.rows || [] }));
  const seen = new Set(); for (const s of list) { let n = s.name, k = 2; while (seen.has(n.toLowerCase())) n = s.name.slice(0, 28) + ' ' + k++; seen.add(n.toLowerCase()); s.name = n; }
  const files = [
    { name: '[Content_Types].xml', data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${list.map((_, i) => `<Override PartName="/xl/worksheets/sheet${i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>` },
    { name: '_rels/.rels', data: '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>' },
    { name: 'xl/workbook.xml', data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${list.map((s, i) => `<sheet name="${x(s.name)}" sheetId="${i + 1}" r:id="rId${i + 1}"/>`).join('')}</sheets><calcPr fullCalcOnLoad="1"/></workbook>` },
    { name: 'xl/_rels/workbook.xml.rels', data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${list.map((_, i) => `<Relationship Id="rId${i + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i + 1}.xml"/>`).join('')}<Relationship Id="rId${list.length + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>` },
    { name: 'xl/styles.xml', data: '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/></cellXfs></styleSheet>' },
    ...list.map((s, i) => ({ name: `xl/worksheets/sheet${i + 1}.xml`, data: sheetXml(s.rows) })),
  ];
  return zip(files);
}

module.exports = { parseCsv, toCsv, zip, xlsx, crc32, col };

// Atlas trading on the PC: the app's side (main process). Accounts and today's numbers in Atlas's data folder;
// the API keys encrypted by Windows for this user (Electron safeStorage = DPAPI), never synced and never shown to the
// page or the model; every action written to Documents/Atlas Bot/Trading/trading-log.csv (it shows in the Library).
// What each tool does is in tradecore.js; the risk engine in traderules.js; the brokers in brokers.js.
'use strict';
const { app, safeStorage, dialog, Notification, BrowserWindow } = require('electron');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const brokers = require('./brokers');
const R = require('./traderules');
const { createTrading } = require('./tradecore');

const FILE = () => path.join(app.getPath('userData'), 'trading.json');
const SECRETS = () => path.join(app.getPath('userData'), 'trading-keys.bin');
const LOG_DIR = () => path.join(app.getPath('documents'), 'Atlas Bot', 'Trading');

function readJson(f, fb) { try { return JSON.parse(fs.readFileSync(f, 'utf8')); } catch { return fb; } }
function writeAtomic(f, text) { const tmp = f + '.tmp'; fs.writeFileSync(tmp, text); fs.renameSync(tmp, f); }

let data = null;
const store = {
  get() { if (!data) data = readJson(FILE(), { accounts: [] }); return data; },
  set(d) { data = d; writeAtomic(FILE(), JSON.stringify(d)); },
};
function secrets() {
  try { if (!fs.existsSync(SECRETS())) return {}; return JSON.parse(safeStorage.decryptString(fs.readFileSync(SECRETS()))); } catch { return {}; }
}
function saveSecrets(all) {
  if (!safeStorage.isEncryptionAvailable()) throw new Error("This PC can't encrypt the keys safely, so Atlas won't store them.");
  const f = SECRETS(), tmp = f + '.tmp';
  fs.writeFileSync(tmp, safeStorage.encryptString(JSON.stringify(all))); fs.renameSync(tmp, f);
}

const csv = (v) => { const s = String(v == null ? '' : v); return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
const COLS = ['at', 'account', 'mode', 'action', 'symbol', 'side', 'qty', 'type', 'price', 'stopLoss', 'takeProfit', 'result', 'orderId', 'note'];
function audit(e) {
  try {
    fs.mkdirSync(LOG_DIR(), { recursive: true });
    const f = path.join(LOG_DIR(), 'trading-log.csv');
    if (!fs.existsSync(f)) fs.writeFileSync(f, COLS.join(',') + '\n');
    fs.appendFileSync(f, COLS.map((k) => csv(k === 'at' ? new Date(e.at).toISOString() : e[k])).join(',') + '\n');
  } catch {}
}
function local() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, '0');
  return { day: `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`, minuteOfDay: d.getHours() * 60 + d.getMinutes(), isoDay: d.getDay() === 0 ? 7 : d.getDay() };
}
function notify(title, body) { try { if (Notification.isSupported()) new Notification({ title, body: String(body || '').slice(0, 240) }).show(); } catch {} }

const core = createTrading({ store, secretFor: (id) => secrets()[id] || null, makeBroker: (a, s) => brokers.make(a, s), audit, local, notify });

// ---------------------------------------------------------------- what the app's page may see and do

/** Accounts without secrets, for Me → Trading and the brief. */
function list() {
  const d = store.get();
  return { killed: !!d.killed, accounts: (d.accounts || []).map((a) => ({ ...a, limits: R.limitsFor(a), today: (d.days || {})[a.id] || null, plan: (d.plans || {})[a.id] || null })) };
}
/** Add or change an account. A secret is only replaced when a new one is given. Changing mode to LIVE asks on screen. */
async function save(win, acc, secret) {
  const d = store.get();
  const accounts = [...(d.accounts || [])];
  const was = accounts.find((x) => x.id === acc.id);
  const a = { id: was ? was.id : 'acct-' + crypto.randomBytes(5).toString('hex'), name: String(acc.name || '').trim().slice(0, 60) || 'Trading account',
    broker: acc.broker === 'projectx' ? 'projectx' : 'bybit', mode: acc.mode === 'live' ? 'live' : 'paper',
    base: acc.broker === 'projectx' ? (String(acc.base || '').trim() || 'https://api.topstepx.com') : undefined,
    remoteId: acc.remoteId != null && acc.remoteId !== '' ? Number(acc.remoteId) : undefined,
    limits: acc.limits || (was && was.limits) || undefined, default: !!acc.default, updatedAt: Date.now() };
  if (a.broker === 'projectx' && !/^https:\/\/[a-z0-9.-]+(:\d+)?$/i.test(a.base)) return { error: 'The prop firm address must look like https://api.topstepx.com' };
  if (a.mode === 'live' && (!was || was.mode !== 'live')) {
    const r = await dialog.showMessageBox(win, { type: 'warning', buttons: ['Make It LIVE', 'Keep It Paper'], defaultId: 1, cancelId: 1, title: 'Real money',
      message: `Make “${a.name}” a LIVE account?`, detail: 'Orders will use real money. Each LIVE order shows you what it is and its worst case, and waits for your OK (or a plan you confirmed). Losses are possible.' });
    if (r.response !== 0) return { error: 'Kept as paper.' };
  }
  if (secret && Object.values(secret).some((v) => v)) { const all = secrets(); all[a.id] = secret; saveSecrets(all); }
  else if (!was) return { error: 'The keys are needed.' };
  const i = accounts.findIndex((x) => x.id === a.id); if (i >= 0) accounts[i] = a; else accounts.push(a);
  store.set({ ...d, accounts });
  return { ok: a.id };
}
function remove(id) {
  const d = store.get();
  store.set({ ...d, accounts: (d.accounts || []).filter((a) => a.id !== id) });
  const all = secrets(); delete all[id]; saveSecrets(all);
  return true;
}
/** Limits are the user's alone (the page, never the model). */
function setLimits(id, limits) {
  const d = store.get(); const accounts = (d.accounts || []).map((a) => a.id === id ? { ...a, limits: cleanLimits(limits), updatedAt: Date.now() } : a);
  store.set({ ...d, accounts }); return true;
}
function cleanLimits(l = {}) {
  const n = (v, lo, hi) => { const x = Number(v); return Number.isFinite(x) ? Math.max(lo, Math.min(hi, x)) : undefined; };
  const out = { maxOrderUsd: n(l.maxOrderUsd, 1, 1e7), maxContracts: n(l.maxContracts, 1, 100), maxDailyLossUsd: n(l.maxDailyLossUsd, 1, 1e7),
    maxOpenPositions: n(l.maxOpenPositions, 1, 50), maxOrdersPerDay: n(l.maxOrdersPerDay, 1, 200),
    symbols: Array.isArray(l.symbols) ? l.symbols.map((s) => String(s).trim().toUpperCase()).filter(Boolean).slice(0, 30) : undefined,
    hours: l.hours && /^\d{1,2}:\d{2}$/.test(l.hours.start || '') && /^\d{1,2}:\d{2}$/.test(l.hours.end || '') ? { start: l.hours.start, end: l.hours.end, days: (l.hours.days || []).filter((x) => x >= 1 && x <= 7) } : null,
    allowDerivatives: !!l.allowDerivatives };
  Object.keys(out).forEach((k) => out[k] === undefined && delete out[k]);
  return out;
}
/** Checks a connection works; for ProjectX also lists the firm's accounts so the user can pick one. */
async function test(acc, secret) {
  try {
    const s = secret && Object.values(secret).some((v) => v) ? secret : secrets()[acc.id];
    if (!s) return { error: 'The keys are needed.' };
    const b = brokers.make({ ...acc, remoteId: acc.remoteId || undefined }, s);
    if (acc.broker === 'projectx') { const list = await b.accounts(); return { ok: true, accounts: list }; }
    const a = await b.account();
    return { ok: true, equity: a.equity };
  } catch (e) { return { error: e.message }; }
}
async function resume(win) {
  const r = await dialog.showMessageBox(win, { type: 'question', buttons: ['Turn Trading Back On', 'Keep It Stopped'], defaultId: 1, cancelId: 1, title: 'Trading', message: 'Turn trading back on?', detail: 'Atlas will be able to place orders again, inside each account\'s limits (LIVE orders still ask you).' });
  if (r.response !== 0) return false;
  core.resume(); return true;
}

/**
 * Pre-approved LIVE limits: LIVE orders inside them go without a tap. Only from Me → Trading, and only after the user
 * confirms in a native dialog (the page and the model can't answer it). lim null turns them off (no dialog needed).
 */
async function setStanding(win, id, lim) {
  if (!lim) { core.setStanding(id, null); return { ok: true }; }
  const a = (store.get().accounts || []).find((x) => x.id === id); if (!a) return { error: 'No such account.' };
  const syms = (Array.isArray(lim.symbols) ? lim.symbols : String(lim.symbols || '').split(/[\s,]+/)).map((x) => String(x).trim().toUpperCase()).filter(Boolean);
  if (!syms.length) return { error: 'List the instruments these limits cover.' };
  const r = await dialog.showMessageBox(win, { type: 'warning', buttons: ['Pre-approve These Trades', 'Cancel'], defaultId: 1, cancelId: 1, title: 'LIVE trading without a tap',
    message: `Let Atlas place LIVE orders on ${a.name} without asking you each time?`,
    detail: `Only ${syms.join(', ')}; at most $${Number(lim.maxOrderUsd) || 0} (spot) or ${Number(lim.maxContracts) || 0} contract(s) per order; at most $${Number(lim.maxDailyLossUsd) || 0} lost in a day; for ${Math.max(1, Math.min(Number(lim.days) || 7, 90))} days. Every account limit still applies, and anything outside these still asks. This is real money: losses are possible.` });
  if (r.response !== 0) return { ok: false };
  const v = core.setStanding(id, lim);
  return v && v.error ? v : { ok: true, standing: v };
}

module.exports = { core, list, save, remove, setLimits, setStanding, test, resume, stopRecord: () => core.stopRecord(), stopFromOther: (rec) => core.stopFromOther(rec), stopAll: (reason) => core.run('trade_stop_all', { reason: reason || 'from the tray' }) };
